const stage22Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_22_1', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'リサイクルとはどういうことですか？', choices: ['使ったものをまた使えるようにすること', 'ごみをそのまま捨てること', '新しいものを買うこと', 'ものを燃やすこと'], correctIndex: 0, feedbackCorrect: 'せいかい！リサイクルは資源を有効に使う大切な行動だよ！', feedbackIncorrect: 'ざんねん！リサイクルは使ったものを材料として再び使えるようにすることだよ！', hintText: 'もう一度つかえるようにする', explanationDetail: 'リサイクル（Recycle）とは、使い終わったものを原料として再び利用することです。ペットボトル→繊維、新聞紙→トイレットペーパーなど。リデュース（減らす）・リユース（再使用）・リサイクルの「3R」が環境保護の基本です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_2', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'ごみを種類ごとに分けることを何といいますか？', choices: ['ごみの分別', 'ごみのリサイクル', 'ごみの収集', 'ごみの処理'], correctIndex: 0, feedbackCorrect: 'せいかい！分別することでリサイクルがしやすくなるよ！', feedbackIncorrect: 'ざんねん！種類ごとに分けることを「分別（ぶんべつ）」というよ！', hintText: '種類ごとに分ける', explanationDetail: 'ごみの分別は環境保護の第一歩です。燃えるごみ・燃えないごみ・資源ごみ（ペットボトル・缶・紙類）などに分けることで、リサイクル率が上がり、焼却処分を減らせます。正しい分別が地球を守ります。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_3', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '電気を使わないときはどうすればよいですか？', choices: ['スイッチを消す', 'そのままにする', '電球を替える', '窓を開ける'], correctIndex: 0, feedbackCorrect: 'せいかい！こまめに消すことで電気を節約できるよ！', feedbackIncorrect: 'ざんねん！使っていない電気はスイッチを消すことが節電の基本だよ！', hintText: 'こまめにオフにする', explanationDetail: '節電（省エネ）は二酸化炭素の排出を減らし、地球温暖化防止に役立ちます。使わない部屋の電気を消す・テレビを見ないときはコンセントを抜く・LED電球に替えるなどの積み重ねが大切です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_4', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: 'マイバッグを持ち歩くとどんなよいことがありますか？', choices: ['プラスチックのごみを減らせる', '荷物が重くなる', '買い物が遅くなる', 'お金がかかる'], correctIndex: 0, feedbackCorrect: 'せいかい！マイバッグでレジ袋を断ることが環境に優しいよ！', feedbackIncorrect: 'ざんねん！マイバッグを使うと不要なプラスチック袋を減らせるよ！', hintText: 'プラスチックを減らす', explanationDetail: 'レジ袋（プラスチック製）は海に流れ込み、海洋生物を傷つけます。マイバッグを使えば年間約20枚のレジ袋削減になります。2020年からレジ袋が有料化され、プラスチック削減の意識が高まっています。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_5', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「もったいない」という考え方はどういうことですか？', choices: ['ものを大切にして無駄にしないこと', 'ものを捨てること', 'ものをたくさん買うこと', 'ものを壊すこと'], correctIndex: 0, feedbackCorrect: 'せいかい！「もったいない」は日本の大切な文化だよ！', feedbackIncorrect: 'ざんねん！「もったいない」はものを最後まで大切に使うことだよ！', hintText: 'むだにしない心がけ', explanationDetail: '「もったいない（MOTTAINAI）」は日本の文化で、ノーベル平和賞受賞者のワンガリ・マータイさんが世界に広めました。ごみを減らす（Reduce）・再使用（Reuse）・再資源化（Recycle）・修理（Repair）の4Rを表す言葉として国際的に注目されています。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_6', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: 'フードロスとはどういうことですか？', choices: ['まだ食べられる食べ物を捨てること', '食べ物を全部食べること', '食べ物を保存すること', '食べ物を作ること'], correctIndex: 0, feedbackCorrect: 'せいかい！フードロスを減らすことが環境と食料問題の解決につながるよ！', feedbackIncorrect: 'ざんねん！フードロスは食べられるのに捨てられる食べ物のことだよ！', hintText: '食べられるのに捨てられる食品', explanationDetail: '日本では年間約472万トン（2022年度）の食品ロスが発生しています。これは国民一人当たり毎日おにぎり約1個分に相当します。食べきれる量だけ買う・賞味期限を確認する・残り物を活用するなどで削減できます。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_7', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '水を大切に使うために家でできることはどれですか？', choices: ['歯みがき中は水を止める', '水をずっと流しっぱなしにする', 'お風呂を毎回換える', '洗い物に熱湯を使う'], correctIndex: 0, feedbackCorrect: 'せいかい！こまめに水を止めると大きな節水になるよ！', feedbackIncorrect: 'ざんねん！歯みがき中に水を止めるだけで1日約6リットルの節水になるよ！', hintText: 'こまめにとめる', explanationDetail: '歯みがき中に水を流しっぱなしにすると1回約6リットルの水を無駄にします。シャワーを1分短縮すると12リットル節約。お風呂の残り湯を洗濯に使うと1回約200リットル節約できます。水は地球上で使える量が限られた大切な資源です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_8', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '公園や道でごみを見つけたときどうするのが良いですか？', choices: ['ごみ箱に捨てるか持ち帰る', 'そのまま置いておく', '川に流す', '土に埋める'], correctIndex: 0, feedbackCorrect: 'せいかい！ひとりひとりの行動が環境を守るよ！', feedbackIncorrect: 'ざんねん！ごみはきちんとごみ箱に捨てるか、持ち帰ろう！', hintText: 'ひろって正しく処理する', explanationDetail: 'ポイ捨てされたごみは雨で川へ流れ、最終的に海を汚染します。世界の海には約1億5000万トンのプラスチックごみが存在すると言われています。地域のごみ拾いボランティア（クリーンアップ活動）に参加することも大切な環境保護活動です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_9', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: 'SDGsの「持続可能な開発目標」とは何を目指していますか？', choices: ['未来の人たちも豊かに生きられる世界をつくること', '今だけ良い生活をすること', '先進国だけが豊かになること', '経済成長だけを追求すること'], correctIndex: 0, feedbackCorrect: 'せいかい！SDGsは今と未来のすべての人が幸せになれる世界を目指しているよ！', feedbackIncorrect: 'ざんねん！SDGsは「誰一人取り残さない」持続可能な世界を目指す17の目標だよ！', hintText: 'みんなが幸せな未来をつくる', explanationDetail: 'SDGs（Sustainable Development Goals）は2015年に国連が採択した17の目標・169のターゲット。2030年までに貧困・飢餓・気候変動などの課題を解決することを目指しています。日本でも学校・企業・地域で取り組みが進んでいます。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_10', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '生物多様性とはどういうことですか？', choices: ['地球上にさまざまな生き物が存在すること', '人間だけが地球に住むこと', '同じ種類の生き物が増えること', '絶滅した動物が復活すること'], correctIndex: 0, feedbackCorrect: 'せいかい！多様な生き物が互いにつながり合って地球の自然が保たれているよ！', feedbackIncorrect: 'ざんねん！生物多様性は地球上にさまざまな種類の生き物が存在していることだよ！', hintText: 'いろいろな生き物がいること', explanationDetail: '地球には約875万種以上の生物が存在します。生物多様性が失われると食物連鎖が崩れ、農業・漁業・医薬品など人間の生活にも大きな影響があります。森林破壊・気候変動・外来種の侵入などが生物多様性を脅かしています。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_11', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「カーボンフットプリント」とは何ですか？', choices: ['ある活動や商品が排出するCO2の量', '足跡の化石のこと', '炭素でできた靴のこと', '森林面積の測定方法'], correctIndex: 0, feedbackCorrect: 'せいかい！商品を作るときに出るCO2の量を知ることが環境選択につながるよ！', feedbackIncorrect: 'ざんねん！カーボンフットプリントは活動や商品が出すCO2の総量のことだよ！', hintText: '排出するCO2の合計量', explanationDetail: 'カーボンフットプリントは製品の製造・輸送・使用・廃棄のすべての過程で排出されるCO2量を示します。商品に表示されることで消費者が環境負荷を比較して選択できます。CO2排出量を減らすことが気候変動対策の核心です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_12', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '再生可能エネルギーに含まれないものはどれですか？', choices: ['石炭', '太陽光', '風力', '水力'], correctIndex: 0, feedbackCorrect: 'せいかい！石炭は化石燃料で、再生不可能なエネルギーだよ！', feedbackIncorrect: 'ざんねん！石炭は燃やすとなくなる化石燃料で、再生可能ではないよ！', hintText: '自然から繰り返し得られないもの', explanationDetail: '再生可能エネルギー：太陽光・風力・水力・地熱・バイオマスなど自然から繰り返し得られるエネルギー。化石燃料（石炭・石油・天然ガス）は数百万年かけて形成され、燃やすと CO2が発生しなくなります。日本では2030年までに再生可能エネルギー比率36〜38%を目標としています。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_13', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'コンポストとは何をするものですか？', choices: ['生ごみを土に還して肥料にすること', '電気を貯めること', '水を浄化すること', '空気を清浄にすること'], correctIndex: 0, feedbackCorrect: 'せいかい！コンポストで生ごみが肥料になりごみを減らせるよ！', feedbackIncorrect: 'ざんねん！コンポストは生ごみを微生物の力で分解して堆肥（たいひ）にすることだよ！', hintText: '生ごみを肥料にする', explanationDetail: 'コンポスト（堆肥化）は野菜くず・果物の皮などを微生物の力で分解し、植物の栄養になる堆肥を作る方法です。家庭から出る生ごみの約30%が堆肥化できるとされています。ごみ削減と土壌改善の一石二鳥の方法です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_14', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'グリーンウォッシュとはどういうことですか？', choices: ['実際より環境に優しいように見せかけること', '環境に配慮した製品を作ること', '植物で建物を飾ること', '緑色の洗剤を使うこと'], correctIndex: 0, feedbackCorrect: 'せいかい！グリーンウォッシュに騙されないように情報を正しく見極めることが大切だよ！', feedbackIncorrect: 'ざんねん！グリーンウォッシュは環境への配慮を誇張・偽装することだよ！', hintText: '環境への良さを見せかける', explanationDetail: 'グリーンウォッシュ（Greenwashing）は「緑（環境）」と「漂白（Whitewash）」を組み合わせた言葉。実態以上に環境に良いと見せかけるマーケティングのことです。消費者は「エコ」「サステナブル」の表示を鵜呑みにせず、具体的な根拠を確認することが重要です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_22_15', stage: LiteracyStage.stage22, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '循環型社会とはどのような社会ですか？', choices: ['ものを作って使って捨てるのではなく、資源を循環させる社会', 'みんなが同じ生活をする社会', '経済が成長し続ける社会', '人口が増え続ける社会'], correctIndex: 0, feedbackCorrect: 'せいかい！循環型社会を目指すことが持続可能な未来につながるよ！', feedbackIncorrect: 'ざんねん！循環型社会は「作って・使って・捨てる」の一方通行ではなく、廃棄物を資源として循環させる社会だよ！', hintText: '資源をぐるぐる回す社会', explanationDetail: '従来の「大量生産・大量消費・大量廃棄」の経済モデルに対し、循環型社会（サーキュラーエコノミー）はごみを出さず、使い終わった製品・素材を新たな資源として活用します。EUでは2050年までの完全循環経済移行を目標にしています。', theme: 'environment'),
];

const stage23Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_23_1', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '地球が暖かくなりすぎることを何といいますか？', choices: ['地球温暖化', '地球冷却', '地震', '台風'], correctIndex: 0, feedbackCorrect: 'せいかい！地球温暖化は今、世界で最も重要な環境問題のひとつだよ！', feedbackIncorrect: 'ざんねん！地球の温度が上がりすぎることを「地球温暖化」というよ！', hintText: '地球の気温が上がること', explanationDetail: '地球温暖化は、人間活動によって大気中の温室効果ガス（主にCO2）が増加し、地球の平均気温が上昇する現象です。産業革命以前と比べ、すでに約1.1℃上昇しています。このまま進むと海面上昇・異常気象・生態系破壊などが深刻化します。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_2', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '太陽の光でつくる発電を何といいますか？', choices: ['太陽光発電', '火力発電', '水力発電', '原子力発電'], correctIndex: 0, feedbackCorrect: 'せいかい！太陽光発電はCO2を出さないクリーンなエネルギーだよ！', feedbackIncorrect: 'ざんねん！太陽の光を使う発電は「太陽光発電」だよ！', hintText: '太陽の光を利用する', explanationDetail: '太陽光発電はソーラーパネルで太陽の光エネルギーを直接電気に変えます。CO2を排出しない再生可能エネルギーで、一度設置すれば約25〜30年使えます。日本では屋根への設置が増え、2030年には電力の約14〜16%を太陽光で賄う目標があります。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_3', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '温室効果ガスのうち最も多く排出されているのはどれですか？', choices: ['二酸化炭素（CO2）', '酸素', '窒素', '水素'], correctIndex: 0, feedbackCorrect: 'せいかい！CO2の削減が温暖化対策の最重要課題だよ！', feedbackIncorrect: 'ざんねん！温暖化の主な原因は二酸化炭素（CO2）だよ！', hintText: '燃やすときに出るガス', explanationDetail: '温室効果ガスはCO2（二酸化炭素）・メタン・N2O（一酸化二窒素）などがあります。CO2は全体の約76%を占め、化石燃料の燃焼・森林伐採などが主な排出源です。温室効果ガスは太陽熱を地球に閉じ込める役割があり、多すぎると気温が上がりすぎます。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_4', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '風の力を使って発電する設備を何といいますか？', choices: ['風力発電機（風車）', '水車', '蒸気機関', '太陽電池'], correctIndex: 0, feedbackCorrect: 'せいかい！大きな風車が風のエネルギーを電気に変えるよ！', feedbackIncorrect: 'ざんねん！風を使って電気を作る装置を「風力発電機（風車）」というよ！', hintText: '風を使って電気を作る', explanationDetail: '風力発電は風の力でプロペラを回し、その回転エネルギーを電気に変えます。CO2を出さないクリーンエネルギーで、洋上（海の上）に設置する洋上風力発電が日本でも普及しています。日本の風力発電量は2030年までに2040万kWを目標としています。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_5', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '地球温暖化で北極・南極の氷が溶けると何が起きますか？', choices: ['海面が上がって陸地が水没する', '気温が下がる', '台風がなくなる', '砂漠が増える'], correctIndex: 0, feedbackCorrect: 'せいかい！島国や海岸沿いの地域が沈む深刻な問題だよ！', feedbackIncorrect: 'ざんねん！氷が解けると海の水が増えて海面が上昇するよ！', hintText: '海水面が変化する', explanationDetail: '北極・南極・山岳の氷河が温暖化で溶けると、海の水が増えて海面が上昇します。現在のペースが続くと2100年までに最大1m以上上昇する予測も。太平洋の島国（ツバルなど）や沿岸都市（東京・大阪の低地）が水没の危機にさらされます。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_6', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: 'パリ協定で決めた目標はどれですか？', choices: ['気温上昇を1.5℃以内に抑えること', '全ての工場を閉鎖すること', '車を全て禁止すること', '森林を全て伐採しないこと'], correctIndex: 0, feedbackCorrect: 'せいかい！パリ協定は196か国が参加した歴史的な合意だよ！', feedbackIncorrect: 'ざんねん！パリ協定は産業革命前からの気温上昇を1.5〜2℃に抑えることを目標にしているよ！', hintText: '気温上昇の上限を決めた国際協定', explanationDetail: 'パリ協定（2015年採択）は196の国・地域が参加した気候変動対策の国際条約。産業革命前からの気温上昇を2℃より十分低く、1.5℃以内に抑えることを目標にしています。各国が自国の削減目標（NDC）を5年ごとに更新して提出します。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_7', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '電気自動車（EV）が環境に良い理由はどれですか？', choices: ['走るときにCO2を出さないから', '速く走れるから', '燃料が安いから', '見た目がきれいだから'], correctIndex: 0, feedbackCorrect: 'せいかい！EVは走行中のCO2排出ゼロが最大のメリットだよ！', feedbackIncorrect: 'ざんねん！電気自動車は走行中にガソリンを燃やさないのでCO2を出さないよ！', hintText: '排気ガスを出さない', explanationDetail: '電気自動車（EV）はバッテリーに蓄えた電気でモーターを動かし、走行中のCO2排出量がゼロです。電力の発電源を再生可能エネルギーにすれば、さらに環境負荷が下がります。2035年までに日本では新車販売をEVなど電動車のみにする目標があります。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_8', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '熱中症が増えているのは地球温暖化と関係がありますか？', choices: ['関係がある', '全く関係ない', '冬だけ関係する', '室内では関係ない'], correctIndex: 0, feedbackCorrect: 'せいかい！温暖化による気温上昇が熱中症リスクを高めているよ！', feedbackIncorrect: 'ざんねん！気温の上昇により、熱中症の発生件数は増加しているよ！', hintText: '気温が上がると体への影響が出る', explanationDetail: '地球温暖化による気温上昇で、猛暑日（最高気温35℃以上）の日数が増加しています。日本での熱中症による救急搬送者数は年々増加し、2018年には約9万5000人に。こまめな水分補給・エアコン利用・屋外活動の調整で予防できます。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_9', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '森林が「CO2の吸収源」と呼ばれる理由は何ですか？', choices: ['木が光合成でCO2を吸収するから', '木が呼吸でCO2を出すから', '森に動物がいるから', '森林で雨が降るから'], correctIndex: 0, feedbackCorrect: 'せいかい！森林を守ることが気候変動対策の重要な柱だよ！', feedbackIncorrect: 'ざんねん！木は光合成によってCO2を吸収し酸素を出すため、温暖化防止に役立つよ！', hintText: '光合成でCO2を取り込む', explanationDetail: '木は光合成で大気中のCO2を吸収し、炭素として幹・枝・根に蓄えます。世界の森林は年間約26億トンのCO2を吸収する「炭素の吸収源」です。しかし熱帯雨林の伐採が進み、毎年東京都の面積の約20倍の森林が失われています。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_10', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: 'ヒートアイランド現象とはどういうことですか？', choices: ['都市部が周辺よりも気温が高くなる現象', '海の水温が上がる現象', '砂漠が広がる現象', '台風が強くなる現象'], correctIndex: 0, feedbackCorrect: 'せいかい！緑地の増加や建物の工夫でヒートアイランドを緩和できるよ！', feedbackIncorrect: 'ざんねん！ヒートアイランドは都市部だけが周囲より気温が高くなる現象だよ！', hintText: '都市が島のように暑くなる', explanationDetail: 'ヒートアイランド現象はアスファルト・コンクリートの蓄熱・エアコン排熱・緑地の減少などが原因で都市部が周辺より2〜3℃高くなる現象。東京では過去100年で3℃以上上昇しています。屋上緑化・街路樹の整備・保水性舗装で緩和できます。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_11', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「カーボンニュートラル」とはどういう状態ですか？', choices: ['CO2の排出量と吸収量がつり合っている状態', 'CO2を全く排出しない状態', 'CO2が大気中から消えた状態', '電気を全く使わない状態'], correctIndex: 0, feedbackCorrect: 'せいかい！排出と吸収のバランスをとることで実質ゼロを目指すよ！', feedbackIncorrect: 'ざんねん！カーボンニュートラルはCO2の排出量から吸収量を引いた実質排出量がゼロの状態だよ！', hintText: '排出と吸収がつり合う', explanationDetail: 'カーボンニュートラル（炭素中立）は排出したCO2を森林吸収・CCS（炭素回収貯留）などで相殺し、実質排出量をゼロにすること。日本は2050年カーボンニュートラルを宣言しています。排出量取引制度・カーボンオフセットなどの政策が活用されます。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_12', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'マイクロプラスチックが問題なのはなぜですか？', choices: ['非常に細かく生き物の体内に入りやすいから', '見た目が汚いから', 'リサイクルできないから', '高価だから'], correctIndex: 0, feedbackCorrect: 'せいかい！マイクロプラスチックは食物連鎖を通じて人間にも影響する深刻な問題だよ！', feedbackIncorrect: 'ざんねん！マイクロプラスチックは5mm以下の微細なプラスチックで生物の体内に入り蓄積されるよ！', hintText: '小さすぎて体に入ってしまう', explanationDetail: 'マイクロプラスチックは5mm以下の微細なプラスチック片。紫外線や波でプラスチックが砕けて生じます。海の魚・貝・海藻に取り込まれ、食物連鎖を通じて人間の体内からも検出されています。健康への影響は研究段階ですが、深刻な懸念があります。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_13', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '環境問題の解決のため、個人ができる最も効果的な行動はどれですか？', choices: ['日常的に省エネ・省資源を心がけること', '専門家だけに任せること', '政府が全て解決すること', '経済発展を止めること'], correctIndex: 0, feedbackCorrect: 'せいかい！一人ひとりの行動の積み重ねが大きな変化をつくるよ！', feedbackIncorrect: 'ざんねん！環境問題は個人・企業・政府が一体となって取り組む必要があるよ！', hintText: '毎日の積み重ねが大切', explanationDetail: '環境問題の解決には政府・企業の取り組みだけでなく、個人の行動変容が重要です。食事の肉を減らす・公共交通を使う・電気を節約する・地産地消を選ぶなどの日常的な行動が大きな変化につながります。一人ひとりが「自分ごと」として考えることが出発点です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_14', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '気候変動の「適応策」とはどういうことですか？', choices: ['すでに起きている変化への対処法を整備すること', 'CO2排出量を減らすこと', '再生可能エネルギーに切り替えること', '森林を増やすこと'], correctIndex: 0, feedbackCorrect: 'せいかい！緩和策と適応策の両方で気候変動に立ち向かうよ！', feedbackIncorrect: 'ざんねん！適応策は気候変動の影響に備えて社会・生活を変えることだよ！', hintText: '変化に合わせて備えること', explanationDetail: '気候変動対策は「緩和策（CO2排出削減）」と「適応策」の2本柱。適応策は「すでに起きている・起きることが確実な変化」への対処で、堤防強化・猛暑対応の農業品種開発・洪水ハザードマップ整備などが含まれます。緩和策だけでは不十分なため、両方が必要です。', theme: 'environment'),
  TaikuQuestion(id: 'tai_23_15', stage: LiteracyStage.stage23, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「気候正義（クライメートジャスティス）」とはどういう考え方ですか？', choices: ['気候変動の被害は貧しい国に多いが、原因は豊かな国にある不公平さを問う考え方', '豊かな国だけが気候変動に対応すればよいという考え方', '気候変動は全員に等しく影響するという考え方', '被害を受けた国だけが対策すればよいという考え方'], correctIndex: 0, feedbackCorrect: 'せいかい！気候正義は国際的な公平性を問う重要な視点だよ！', feedbackIncorrect: 'ざんねん！気候正義は「排出量が少ないのに被害が大きい国・人々がいる」不公平さを問う考え方だよ！', hintText: '被害と原因の不公平さを問う', explanationDetail: '気候変動の影響は途上国・島嶼国・貧困層に最も深刻ですが、歴史的なCO2排出量は先進国が圧倒的に多くなっています。「誰が被害を受け、誰が責任を負うべきか」という公平性の問題が気候正義（クライメートジャスティス）の核心です。COP会議での先進国の資金援助はこの文脈で議論されます。', theme: 'environment'),
];

const stage24Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_24_1', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '銀行にお金を預けるとどうなりますか？', choices: ['安全に保管されて利子がつくことがある', 'なくなってしまう', '増えすぎてしまう', '使えなくなる'], correctIndex: 0, feedbackCorrect: 'せいかい！銀行はお金を安全に預かってくれる大切な場所だよ！', feedbackIncorrect: 'ざんねん！銀行に預けると安全に保管され、利息がつくことがあるよ！', hintText: '安全に預かってもらえる', explanationDetail: '銀行（預金）はお金を安全に保管し、預金額に応じて利子（利息）がつきます。日本では銀行が倒産しても1000万円までは預金保険制度で保護されます。銀行は集めたお金を企業や個人に貸し付け、経済を動かす役割も果たしています。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_2', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「利子（利息）」とはどういうものですか？', choices: ['お金を預けたり貸したりした対価として受け取れるお金', '銀行への入会金', '商品の消費税', 'ATM手数料'], correctIndex: 0, feedbackCorrect: 'せいかい！利子はお金を貸し借りしたときに発生するお金だよ！', feedbackIncorrect: 'ざんねん！利子（利息）は預けたお金や貸したお金に対してもらえる報酬のことだよ！', hintText: 'お金を預けた報酬', explanationDetail: '利子（利息）はお金の貸し借りの対価です。銀行にお金を預けると銀行から利息を受け取れます（預金金利）。逆に銀行からお金を借りると利息を支払います（借入金利）。金利は経済の状況によって変わります。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_3', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'キャッシュレス決済とはどういう支払い方法ですか？', choices: ['現金を使わずにカードやスマホで払う方法', '現金で支払う方法', '物々交換する方法', 'ポイントだけで払う方法'], correctIndex: 0, feedbackCorrect: 'せいかい！キャッシュレスは便利だけど使いすぎないよう管理が大切だよ！', feedbackIncorrect: 'ざんねん！キャッシュレスはクレジットカード・電子マネー・スマホ決済などの現金以外での支払いだよ！', hintText: '現金を使わないで払う', explanationDetail: 'キャッシュレス決済にはクレジットカード・デビットカード・電子マネー（Suica等）・QRコード決済（PayPay等）があります。日本のキャッシュレス比率は約36%（2022年）で、政府は2025年までに40%を目標にしています。便利な反面、使いすぎに注意が必要です。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_4', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: 'クレジットカードで買い物した場合、お金はいつ引き落とされますか？', choices: ['後日まとめて引き落とされる', '買った瞬間にすぐ引き落とされる', '1年後にまとめて払う', '払わなくていい'], correctIndex: 0, feedbackCorrect: 'せいかい！後払いだから使いすぎに注意が必要だよ！', feedbackIncorrect: 'ざんねん！クレジットカードは後払い（翌月など）でまとめて引き落とされるよ！', hintText: '後払いの仕組み', explanationDetail: 'クレジットカードは「信用（Credit）」を担保に後払いで決済する仕組みです。通常翌月に銀行口座から引き落とされます。便利ですが、手持ちのお金以上に使えてしまうため、残高を常に把握し支払い能力の範囲で使うことが重要です。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_5', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '「予算」を立てる目的は何ですか？', choices: ['お金の使い方を計画して管理するため', 'お金を多く見せるため', '買い物を禁止するため', '税金を節約するため'], correctIndex: 0, feedbackCorrect: 'せいかい！予算を立てると計画的にお金を使えるよ！', feedbackIncorrect: 'ざんねん！予算は収入と支出を計画して、お金を上手に管理するためのものだよ！', hintText: 'お金の計画を立てる', explanationDetail: '予算とは収入と支出を事前に計画すること。家庭では「食費・光熱費・娯楽費」など項目別に使えるお金を決めます。予算を守ることで貯金ができ、急な出費にも対応できます。家計簿アプリを使うと記録が楽になります。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_6', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '投資とは何ですか？', choices: ['将来の利益を期待してお金を使うこと', 'お金を捨てること', 'お金を全部使うこと', '銀行に預けること'], correctIndex: 0, feedbackCorrect: 'せいかい！投資はリスクもあるけど将来の資産形成に大切だよ！', feedbackIncorrect: 'ざんねん！投資は将来の利益を期待して株式・債券・不動産などにお金を使うことだよ！', hintText: '将来の利益のためにお金を使う', explanationDetail: '投資は株式・債券・不動産・投資信託などにお金を使い、将来の利益（配当・値上がり益）を期待すること。元本割れのリスクがありますが、長期的には資産を増やせる可能性があります。日本ではNISA（少額投資非課税制度）で投資しやすい環境が整備されています。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_7', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「インフレ（インフレーション）」とはどういうことですか？', choices: ['物の値段が全体的に上がること', '物の値段が全体的に下がること', 'お金の量が減ること', '給料が上がること'], correctIndex: 0, feedbackCorrect: 'せいかい！インフレのとき、お金の価値は相対的に下がるよ！', feedbackIncorrect: 'ざんねん！インフレは物価が上昇する現象だよ！', hintText: '物価が上がる', explanationDetail: 'インフレーション（物価上昇）は同じお金で買えるものが減ることを意味し、お金の価値が下がります。適度なインフレは経済が成長している証拠ですが、急激なインフレは生活を圧迫します。日本銀行は物価安定を目標に金融政策を行っています。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_8', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '家計の収入と支出のバランスで、赤字はどういう状態ですか？', choices: ['支出が収入より多い状態', '収入が支出より多い状態', '収入と支出が同じ状態', 'お金が全くない状態'], correctIndex: 0, feedbackCorrect: 'せいかい！赤字が続くと貯金が減って生活が困難になるよ！', feedbackIncorrect: 'ざんねん！赤字は「使ったお金が入ってきたお金より多い」状態だよ！', hintText: '使いすぎている状態', explanationDetail: '家計が赤字になると貯金を取り崩すか借金が増えます。赤字の主な原因は固定費（家賃・通信費）の高さ・衝動買い・外食の多さなど。収支を記録し、固定費の見直し・不要な支出カットで黒字化を目指しましょう。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_9', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '「複利」とはどういう仕組みですか？', choices: ['利息にも利息がつくこと', '利息が2倍になること', '銀行手数料が増えること', '税金が複数かかること'], correctIndex: 0, feedbackCorrect: 'せいかい！複利は「お金がお金を生む」強力な仕組みだよ！', feedbackIncorrect: 'ざんねん！複利は「利息にも利息がつく」ことで雪だるま式にお金が増える仕組みだよ！', hintText: '利息に利息がつく', explanationDetail: '複利は元金+利息を合わせた金額に対して次回の利息が計算されます。アインシュタインは「複利は人類最大の発明」と言ったとされています。例：100万円を年利5%の複利で10年運用→163万円。長期投資で複利の効果が最大化します。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_10', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '「分散投資」が大切な理由はなぜですか？', choices: ['一つの投資が失敗しても全体の損失を減らせるから', 'お金が素早く増えるから', '手数料が安くなるから', '税金がかからないから'], correctIndex: 0, feedbackCorrect: 'せいかい！「卵は一つのかごに盛るな」が分散投資の基本だよ！', feedbackIncorrect: 'ざんねん！分散投資はリスクを分散してひとつが失敗しても全体への影響を減らすためだよ！', hintText: 'リスクを分散する', explanationDetail: '分散投資は「一つのかごに全ての卵を入れない」という考え方。株式・債券・不動産・現金など複数に分けて投資することで、一つが値下がりしても他でカバーできます。国内外・産業分野・資産クラスの分散が基本的なリスク管理手法です。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_11', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '株式を持つことで得られる権利はどれですか？', choices: ['会社の一部の所有権と利益の分配（配当）を受ける権利', '会社に命令できる権利', '無料で商品をもらえる権利', '銀行から借金できる権利'], correctIndex: 0, feedbackCorrect: 'せいかい！株主は会社の一部のオーナーとして配当や議決権を持つよ！', feedbackIncorrect: 'ざんねん！株主は会社の一部の所有者として、配当（利益の分配）や株主総会での議決権を得るよ！', hintText: '会社の一部のオーナー', explanationDetail: '株式を購入すると「株主」として会社の一部を所有します。権利：①配当（会社の利益の分配）②株主優待（商品・割引券等）③議決権（株主総会で会社の方針に投票）。リスク：株価が下がると損失が発生します。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_12', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '為替レートが「1ドル=150円」から「1ドル=120円」に変わったとき何が起きますか？', choices: ['円高になり、輸入品が安くなる', '円安になり、輸出企業が苦しくなる', '何も変わらない', '物価が上がる'], correctIndex: 0, feedbackCorrect: 'せいかい！円高は輸入に有利で、海外旅行も安くなるよ！', feedbackIncorrect: 'ざんねん！1ドルに必要な円が減ることは円の価値が上がる（円高）ということで、輸入品が安くなるよ！', hintText: '必要な円が減ると円の価値が高い', explanationDetail: '為替レートは異なる通貨の交換比率。1ドル=150円→120円は円高（円の価値上昇）。影響：輸入品が安くなる（食料・エネルギーなど）・海外旅行が安くなる一方、輸出企業（自動車・電機）は利益が減りにくい。逆の円安は輸出に有利です。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_13', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「フィンテック（FinTech）」とはどういう分野ですか？', choices: ['金融と技術を組み合わせた新しいサービス', 'フィットネスと金融の組み合わせ', '農業と金融の組み合わせ', '芸術と技術の組み合わせ'], correctIndex: 0, feedbackCorrect: 'せいかい！フィンテックはお金の未来を変える革新的な分野だよ！', feedbackIncorrect: 'ざんねん！フィンテック（FinTech）はFinance（金融）＋Technology（技術）で、お金のデジタル革新のことだよ！', hintText: '金融＋テクノロジー', explanationDetail: 'フィンテック（FinTech）はスマホ決済・仮想通貨・AI融資審査・ロボアドバイザー（AI投資）・ブロックチェーンなど金融サービスの技術革新の総称。従来の銀行・証券会社の業務を変え、誰でも手軽に金融サービスを使える時代を実現しています。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_14', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「経済格差」が広がるとどのような問題が起きますか？', choices: ['教育・医療・機会の不平等が生まれる', '全員の生活水準が下がる', '国の税収が増える', '経済成長が加速する'], correctIndex: 0, feedbackCorrect: 'せいかい！格差は単なる経済問題ではなく、社会全体の問題だよ！', feedbackIncorrect: 'ざんねん！経済格差は教育の機会・医療へのアクセス・社会参加の不平等につながるよ！', hintText: '機会の不平等が生まれる', explanationDetail: '経済格差が拡大すると、富裕層は良質な教育・医療を受けられる一方、貧困層はその機会を奪われます。日本の子どもの貧困率は約11%（2019年）。親の経済力が子どもの学力・進学率に影響する「貧困の連鎖」が問題になっています。累進課税・社会保障制度などが格差是正の手段です。', theme: 'money'),
  TaikuQuestion(id: 'tai_24_15', stage: LiteracyStage.stage24, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'マイクロファイナンスとはどういうものですか？', choices: ['途上国の貧しい人々に少額融資で自立を支援する仕組み', '大企業への融資制度', '政府への資金援助', '株式投資の一種'], correctIndex: 0, feedbackCorrect: 'せいかい！マイクロファイナンスは貧困から自立する力を与えるよ！', feedbackIncorrect: 'ざんねん！マイクロファイナンスは銀行口座を持てない貧困層に小額を融資し起業・自立を支援する仕組みだよ！', hintText: '貧しい人への少額融資', explanationDetail: 'マイクロファイナンスは担保なしで少額を融資し、自営業・農業で収入を得る手助けをする金融サービス。バングラデシュのグラミン銀行創始者ムハマド・ユヌスがノーベル平和賞（2006年）を受賞。途上国の女性の経済的自立に特に効果を発揮しています。', theme: 'money'),
];

const stage25Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_25_1', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '税金は何のために集めますか？', choices: ['みんなが使う道路・学校・病院などをつくるため', '政治家だけのため', '銀行に渡すため', '外国に送るため'], correctIndex: 0, feedbackCorrect: 'せいかい！税金は社会全体のためのお金だよ！', feedbackIncorrect: 'ざんねん！税金は道路・学校・警察・病院など社会の基盤を作るために使われるよ！', hintText: 'みんなで社会を支えるお金', explanationDetail: '税金は国・都道府県・市区町村が集め、道路・橋・学校・公園・警察・消防・医療・年金など公共サービスの費用に使われます。税金がなければ現在の社会インフラは成り立ちません。「税は社会の会費」とも表現されます。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_2', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '買い物のとき商品の値段に加えてかかる税金を何といいますか？', choices: ['消費税', '所得税', '固定資産税', '相続税'], correctIndex: 0, feedbackCorrect: 'せいかい！消費税は買い物のたびにかかる身近な税金だよ！', feedbackIncorrect: 'ざんねん！買い物のときに払う税金を「消費税」というよ！', hintText: 'ものを買うときにかかる税', explanationDetail: '消費税は商品・サービスを消費したときにかかる税金。日本では2019年から10%（食料品・新聞は軽減税率8%）。消費税は誰もが公平に負担しますが、収入が少ない人ほど負担割合が高い（逆進性）という課題もあります。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_3', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '社会保険の目的は何ですか？', choices: ['病気・けが・老後など困ったときにみんなで助け合うこと', 'お金を増やすこと', '会社の利益を守ること', '政府の資金を増やすこと'], correctIndex: 0, feedbackCorrect: 'せいかい！社会保険はみんなで支え合う助け合いの仕組みだよ！', feedbackIncorrect: 'ざんねん！社会保険は病気・失業・老後などのリスクに備えてみんなで助け合う制度だよ！', hintText: 'みんなで助け合う仕組み', explanationDetail: '社会保険には健康保険（医療費の一部を保険で賄う）・年金保険（老後の生活を支える）・雇用保険（失業時の生活を支援）・介護保険（要介護時のサポート）・労災保険（仕事中のケガ）があります。保険料を全員で出し合い、困ったときに受け取れます。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_4', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '「年金」はどういう仕組みですか？', choices: ['働いている世代がお金を出して高齢者の生活を支える仕組み', 'お金を自分で貯める仕組み', '会社が一方的に渡すお金', '税金だけで賄われるお金'], correctIndex: 0, feedbackCorrect: 'せいかい！年金は世代間の助け合いで成り立っているよ！', feedbackIncorrect: 'ざんねん！年金は今働いている世代が保険料を出し、その世代が老後に受け取る「世代間の助け合い」だよ！', hintText: '世代をまたいだ助け合い', explanationDetail: '日本の公的年金は「賦課方式」で、現役世代が払った保険料がそのまま今の高齢者の年金に使われます。少子高齢化が進む日本では現役世代1人当たりの負担が増加しています。個人が将来に備える「私的年金（iDeCo等）」との組み合わせも重要になっています。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_5', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '「最低賃金」とは何ですか？', choices: ['法律で決められた時給の最低金額', '一番高い給料', '残業代の計算方法', '社長の給料'], correctIndex: 0, feedbackCorrect: 'せいかい！最低賃金は労働者を守るための大切なルールだよ！', feedbackIncorrect: 'ざんねん！最低賃金は法律で定められた「これ以下では払ってはいけない」時間当たりの最低金額だよ！', hintText: '法律で決められた最低の時給', explanationDetail: '最低賃金は労働者の生活を守るために法律（最低賃金法）で定められています。都道府県別に異なり、2024年の全国加重平均は1055円。雇用主は最低賃金以上を払う義務があり、違反した場合は罰則があります。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_6', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '国の借金（国債）が増えると将来どうなる可能性がありますか？', choices: ['将来の世代が返済の負担を背負うことになる', '何も問題ない', '国が豊かになる', 'すぐ経済崩壊する'], correctIndex: 0, feedbackCorrect: 'せいかい！持続可能な財政が将来の世代のためになるよ！', feedbackIncorrect: 'ざんねん！国債は将来の税収から返済されるため、将来世代の負担になる可能性があるよ！', hintText: '将来世代への負担', explanationDetail: '国債は政府が発行する借用証書で、将来の税収で返済されます。日本の国債残高は約1000兆円超（2024年）で、GDP比約250%と主要国で最高水準。このまま増え続けると将来世代の税負担が増えます。財政健全化と経済成長のバランスが課題です。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_7', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「ふるさと納税」はどういう制度ですか？', choices: ['好きな自治体に寄付して税金を控除してもらえる制度', '故郷への強制的な送金', '田舎に引越しする制度', '農業への補助金'], correctIndex: 0, feedbackCorrect: 'せいかい！ふるさと納税は自分の意思で支援先を選べる税の仕組みだよ！', feedbackIncorrect: 'ざんねん！ふるさと納税は任意の自治体に寄付し、その分が住民税・所得税から控除される制度だよ！', hintText: '好きな自治体を応援できる税', explanationDetail: 'ふるさと納税は2008年に創設。好きな自治体に寄付すると返礼品（地域特産品）を受け取れ、寄付額-2000円が所得税・住民税から控除されます。2023年の寄付総額は約1兆円超。地方の財源確保と地域活性化に役立っています。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_8', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「消費者の権利」に含まれないものはどれですか？', choices: ['だまされても文句を言わない権利', '安全を求める権利', '正確な情報を得る権利', '意見を反映させる権利'], correctIndex: 0, feedbackCorrect: 'せいかい！消費者には知る権利・安全の権利・意見を反映させる権利などがあるよ！', feedbackIncorrect: 'ざんねん！消費者はだまされたとき訴える権利を持っているよ！', hintText: '消費者として守られる権利', explanationDetail: 'JF・ケネディが提唱した消費者の4つの権利：①安全の権利②知る権利③選択の権利④意見を反映させる権利。日本では消費者基本法で消費者の権利が守られています。詐欺・欠陥商品・誇大広告などで被害を受けた場合は消費生活センターに相談できます。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_9', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: 'GDP（国内総生産）とは何を表す指標ですか？', choices: ['ある国で1年間に生み出された価値（財・サービス）の合計', '国の人口の合計', '国の借金の合計', '国内の会社の数'], correctIndex: 0, feedbackCorrect: 'せいかい！GDPは国の経済規模を示す最も重要な指標のひとつだよ！', feedbackIncorrect: 'ざんねん！GDPは「Gross Domestic Product」で国内で1年間に生産された全ての財・サービスの総額だよ！', hintText: '国の経済規模を示す指標', explanationDetail: 'GDP（国内総生産）は国の経済力・規模を示す代表的な指標。日本のGDPは約560兆円（2023年）で世界第4位。GDP成長率がプラスなら経済成長、マイナスが2四半期続くと「景気後退（リセッション）」です。ただしGDPだけでは幸福度や格差は測れません。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_10', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '累進課税とはどういう仕組みですか？', choices: ['収入が多いほど税率が高くなる仕組み', '全員が同じ金額を払う仕組み', '収入が少ないほど税率が高くなる仕組み', '会社だけに課税する仕組み'], correctIndex: 0, feedbackCorrect: 'せいかい！累進課税は経済格差を縮小するための重要な仕組みだよ！', feedbackIncorrect: 'ざんねん！累進課税は高収入の人ほど高い税率が適用される仕組みだよ！', hintText: '稼ぐほど税率が上がる', explanationDetail: '累進課税（所得税・相続税など）は収入・財産が多いほど高い税率を課すことで経済格差を是正します。日本の所得税率は5%〜45%の7段階。高所得者が多く税金を払い、その税収が教育・福祉・インフラに使われることで、機会の平等を目指します。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_11', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '少子高齢化が経済に与える最も深刻な影響はどれですか？', choices: ['労働力不足と社会保障費の増大', '人口増加による住宅不足', 'インフレの抑制', '企業の海外進出増加'], correctIndex: 0, feedbackCorrect: 'せいかい！少子高齢化は日本が直面する最重要課題のひとつだよ！', feedbackIncorrect: 'ざんねん！少子高齢化は働く人が減って社会保障を支えにくくなる深刻な問題だよ！', hintText: '働く人が減り社会保障費が増える', explanationDetail: '日本の高齢化率は29%超（2024年）で世界最高水準。課題：①労働力不足→経済成長の鈍化②税・保険料を払う現役世代減少③年金・医療・介護費の増大。対策：女性・高齢者・外国人労働力の活用・AI/ロボット化・出生率向上策などが検討されています。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_12', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「社会的企業（ソーシャルエンタープライズ）」とはどういう会社ですか？', choices: ['利益を追求しながら社会問題の解決も目指す会社', '政府が運営する会社', '利益のみを追求する会社', 'NPOのことをいう'], correctIndex: 0, feedbackCorrect: 'せいかい！ビジネスを通じて社会問題を解決する新しい企業の形だよ！', feedbackIncorrect: 'ざんねん！社会的企業は利益（ビジネスの持続）と社会的使命（課題解決）の両立を目指す企業だよ！', hintText: '利益と社会貢献を両立する', explanationDetail: '社会的企業（ソーシャルエンタープライズ）は環境・貧困・教育・雇用など社会問題をビジネスで解決することを使命とします。B Corp認証・ベネフィットコーポレーションなどの枠組みも登場。「利益か社会貢献か」の二択から「両立」へのビジネスの進化です。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_13', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'UBI（ユニバーサル・ベーシックインカム）とはどういう政策ですか？', choices: ['すべての市民に無条件で定期的に現金を給付する制度', '働いた人だけに給付される手当', '企業への補助金', '高所得者への税還付'], correctIndex: 0, feedbackCorrect: 'せいかい！UBIは貧困・格差・AI失業に対応する革新的な政策として世界で議論されているよ！', feedbackIncorrect: 'ざんねん！UBIはすべての人に条件なく定額を給付する制度だよ！', hintText: '全員に無条件で現金を渡す', explanationDetail: 'UBI（ユニバーサル・ベーシックインカム）は収入・就労状況に関係なく全員に一定額を給付する政策。賛成意見：貧困解消・官僚的手続き不要・AIによる雇用喪失への対応。反対意見：財源確保困難・労働意欲低下の懸念。フィンランドなどで試験的実施が行われています。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_14', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'グローバル化が経済に与えたデメリットはどれですか？', choices: ['賃金格差や特定産業の衰退が起きやすい', 'すべての人が豊かになった', '文化の多様性が失われた', '国際紛争が増えた'], correctIndex: 0, feedbackCorrect: 'せいかい！グローバル化には恩恵とともに課題もあるよ！', feedbackIncorrect: 'ざんねん！グローバル化は便利な反面、賃金の下押し圧力や国内産業への打撃というデメリットもあるよ！', hintText: '国際競争で負ける産業も生まれる', explanationDetail: 'グローバル化のメリット：貿易拡大・消費者へのより安い商品・技術交流。デメリット：低賃金国との競争で国内の賃金が上がりにくい・製造業の空洞化・サプライチェーンリスク（パンデミック時の供給不足）。経済的利益の分配が偏る問題も議論されています。', theme: 'money'),
  TaikuQuestion(id: 'tai_25_15', stage: LiteracyStage.stage25, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'ESG投資とは何を考慮した投資ですか？', choices: ['環境・社会・ガバナンスを重視した企業への投資', '利益だけを重視した投資', '短期的な株価上昇を狙う投資', '政府債券だけへの投資'], correctIndex: 0, feedbackCorrect: 'せいかい！ESG投資は持続可能な経済を作るための重要な仕組みだよ！', feedbackIncorrect: 'ざんねん！ESGはEnvironment（環境）・Social（社会）・Governance（企業統治）の頭文字で、これらを考慮した企業に投資することだよ！', hintText: '環境・社会・ガバナンスを重視', explanationDetail: 'ESG投資は財務情報だけでなく環境（温暖化対策・脱炭素）・社会（人権・労働条件）・ガバナンス（経営の透明性）も評価して投資判断します。世界のESG投資残高は約35兆ドル（2022年）。長期的にはESGに優れた企業が安定した利益を生むという考え方が広まっています。', theme: 'money'),
];

const stage26Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_26_1', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「人権」とはどういうものですか？', choices: ['全ての人が生まれながらに持つ大切な権利', '大人だけが持つ権利', 'お金持ちだけが持つ権利', '特別な人だけが持つ権利'], correctIndex: 0, feedbackCorrect: 'せいかい！人権はすべての人に生まれながら備わっている権利だよ！', feedbackIncorrect: 'ざんねん！人権は「人間として生まれたすべての人が平等に持っている権利」だよ！', hintText: '生まれながらに持つ権利', explanationDetail: '人権（Human Rights）は人間が生まれながらに持つ基本的な権利で、侵してはならないものです。世界人権宣言（1948年）は「すべての人間は生まれながら自由で平等な尊厳と権利を持つ」と宣言しています。日本国憲法でも基本的人権の尊重が保障されています。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_2', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「差別」はなぜいけないのですか？', choices: ['全ての人は平等な価値を持ち、不当に扱われるべきでないから', '法律で禁止されているから', '先生が怒るから', '見た目が悪いから'], correctIndex: 0, feedbackCorrect: 'せいかい！差別は人の尊厳を傷つける行為だよ！', feedbackIncorrect: 'ざんねん！差別がいけない一番の理由は、全ての人が平等な価値を持つ人間だからだよ！', hintText: '全員が同じ価値を持つ人間だから', explanationDetail: '差別とは人種・性別・国籍・障がい・宗教などを理由に不当な扱いをすることです。差別は人の尊厳を傷つけ、社会の分断を生みます。日本には部落差別・在日外国人差別・障がい者差別などの問題があります。一人ひとりが違いを認め合い、互いを尊重することが大切です。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_3', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'インクルーシブ教育とはどういう教育ですか？', choices: ['障がいのある子もない子も共に学ぶ教育', '才能のある子だけの教育', '外国人だけの教育', '大人のための教育'], correctIndex: 0, feedbackCorrect: 'せいかい！インクルーシブ教育はみんなが共に学べる環境をつくるよ！', feedbackIncorrect: 'ざんねん！インクルーシブ教育は障がいの有無に関わらず全ての子どもが同じ場で学ぶ教育だよ！', hintText: 'みんなが共に学ぶ', explanationDetail: 'インクルーシブ教育（inclusive education）は障がいのある子どもとない子どもが可能な限り同じ環境で共に学ぶ教育。「誰ひとり排除しない」という理念に基づきます。教室のバリアフリー化・補助教員配置・特別なサポートなどで実現します。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_4', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: 'バリアフリーとはどういうことですか？', choices: ['障がいのある人が生活しやすいように障壁（バリア）をなくすこと', '塀をなくすこと', '試験をなくすこと', '部屋を広くすること'], correctIndex: 0, feedbackCorrect: 'せいかい！バリアフリーはすべての人が生活しやすい社会をつくるよ！', feedbackIncorrect: 'ざんねん！バリアフリーは段差・扉・距離など障がいのある人の前に立ちはだかる「壁（バリア）」をなくすことだよ！', hintText: '障壁（バリア）をなくす', explanationDetail: 'バリアフリーは車いすの人が通れるスロープ・点字ブロック・エレベーター・音響信号機などを整備して、身体的な障がいのある人が自由に移動・生活できる環境を作ることです。物理的バリアの除去だけでなく、情報・心理的・制度的バリアの除去も重要です。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_5', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: 'LGBTQとはどういう人たちですか？', choices: ['性的少数者（性別・性的指向が多数派と異なる人）の総称', '特定の国の人々', '特別な病気の人たち', '外国人の人たち'], correctIndex: 0, feedbackCorrect: 'せいかい！LGBTQの人たちも同じ価値と権利を持つ大切な存在だよ！', feedbackIncorrect: 'ざんねん！LGBTQはレズビアン・ゲイ・バイセクシュアル・トランスジェンダー・クィアなど性的少数者の総称だよ！', hintText: '多様な性のあり方を持つ人たち', explanationDetail: 'LGBTQ+はLesbians・Gay・Bisexual・Transgender・Queer/Questioningの頭文字。日本では人口の約3〜10%程度とされています。同性パートナーシップ制度を導入する自治体が増えていますが、法的な同性婚は未実現です。多様な性のあり方を尊重することが人権の尊重につながります。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_6', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '子どもの権利条約で定められた子どもの4つの権利に含まれないものはどれですか？', choices: ['働く権利（労働権）', '生きる権利', '育つ権利', '参加する権利'], correctIndex: 0, feedbackCorrect: 'せいかい！子どもには強制的な労働をさせない権利が保護されているよ！', feedbackIncorrect: 'ざんねん！子どもの権利条約の4原則は「生きる・育つ・守られる・参加する」権利だよ！', hintText: '子どもの4原則に含まれる権利', explanationDetail: '国連子どもの権利条約（1989年）の4原則：①生きる権利（健康・医療）②育つ権利（教育・遊び）③守られる権利（虐待・差別からの保護）④参加する権利（意見を言える）。日本は1994年に批准しています。児童労働は第32条で禁止されています。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_7', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: 'ジェンダーとセックスの違いは何ですか？', choices: ['セックスは生物学的性別、ジェンダーは社会的・文化的な性別役割', '全く同じ意味', 'セックスは個人的、ジェンダーは公的', 'ジェンダーは見た目の性別'], correctIndex: 0, feedbackCorrect: 'せいかい！生物学的性別と社会的性別の役割は別の概念だよ！', feedbackIncorrect: 'ざんねん！セックス（sex）は生物学的な性差、ジェンダー（gender）は社会・文化が作った性別役割のことだよ！', hintText: '生物学的性別と社会的役割の区別', explanationDetail: 'セックス（sex）は男性・女性などの生物学的性差（染色体・生殖器）。ジェンダー（gender）は「男らしさ・女らしさ」など社会・文化が作り出した役割・規範・期待のことです。「男は泣いてはいけない」「女は家事をすべき」はジェンダー規範。ジェンダー平等はこれらの偏見・固定観念をなくすことです。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_8', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: 'アンコンシャス・バイアスとはどういうことですか？', choices: ['無意識に持っている偏見・先入観', '意識的な差別行為', '科学的に証明された事実', '文化的な慣習'], correctIndex: 0, feedbackCorrect: 'せいかい！アンコンシャス・バイアスに気づくことが平等な社会への第一歩だよ！', feedbackIncorrect: 'ざんねん！アンコンシャス・バイアスは自分では気づいていない無意識の偏見のことだよ！', hintText: '気づかない偏見・思い込み', explanationDetail: 'アンコンシャス・バイアス（Unconscious Bias）は意識せずに持つ先入観や固定観念。例：「リーダーは男性」「女性は感情的」「〇〇人はこういう性格」など。これが採用・評価・機会に影響します。自分のバイアスに気づく「メタ認知」が多様性を尊重する第一歩です。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_9', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: 'アファーマティブ・アクション（積極的格差是正措置）とはどういうことですか？', choices: ['歴史的に不利な立場に置かれてきたグループを積極的に支援する政策', '強い人をもっと優遇する政策', '競争を廃止する政策', '全員を同じ扱いにする政策'], correctIndex: 0, feedbackCorrect: 'せいかい！過去の不平等を積極的に是正する取り組みだよ！', feedbackIncorrect: 'ざんねん！アファーマティブ・アクションは差別で不利な立場に置かれてきた人々を積極的に支援する措置だよ！', hintText: '過去の不平等を積極的に是正する', explanationDetail: 'アファーマティブ・アクションは人種・性別・障がいなどによる歴史的な差別・不平等を是正するため、採用・入学などで一定の機会を保障する政策。女性役員クオータ制・障がい者雇用率・大学の多様性入試などが例です。「真の平等のためには格差の積極的是正が必要」という考え方です。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_10', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: 'ヘイトスピーチとはどういうことですか？', choices: ['人種・民族・性別などを理由に憎悪や差別を煽る発言', '政府への批判', '意見の違いを表明すること', '激しい議論をすること'], correctIndex: 0, feedbackCorrect: 'せいかい！ヘイトスピーチは人の尊厳を傷つける許されない行為だよ！', feedbackIncorrect: 'ざんねん！ヘイトスピーチは人種・民族・性別・宗教などを理由に憎しみや差別を煽る言動のことだよ！', hintText: '特定グループへの憎悪をあおる言葉', explanationDetail: 'ヘイトスピーチ（Hate Speech）は人種・民族・宗教・性別・性的指向などを理由に特定グループへの憎悪・差別・暴力を煽る言動。日本では2016年にヘイトスピーチ解消法が制定されましたが、罰則はありません。表現の自由と人の尊厳の保護のバランスが課題です。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_11', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「難民」と「移民」の違いは何ですか？', choices: ['難民は迫害・紛争から逃げた人、移民は自らの意思で移住した人', '難民は外国人、移民は日本人', '全く同じ意味', '難民は貧しい人、移民は裕福な人'], correctIndex: 0, feedbackCorrect: 'せいかい！難民の定義と権利を正しく理解することが大切だよ！', feedbackIncorrect: 'ざんねん！難民は迫害・戦争・紛争から逃れた人、移民は主に経済・家族などの理由で自発的に移住した人だよ！', hintText: '逃げた理由が違う', explanationDetail: '難民は「人種・宗教・国籍・政治的意見・特定の社会集団への属性」を理由に迫害される恐れがある人（難民条約定義）。世界の難民数は約1億1000万人（2023年）。日本の難民認定率は約2%で国際的に低水準。難民条約は1951年に採択されています。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_12', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「普遍的人権」の考え方に反論する「文化相対主義」とはどういう立場ですか？', choices: ['人権の基準は文化・社会によって異なるという立場', '人権は全て同じという立場', '人権は経済力で決まるという立場', '人権は政府が与えるという立場'], correctIndex: 0, feedbackCorrect: 'せいかい！普遍的人権と文化相対主義の議論は国際社会の重要な議題だよ！', feedbackIncorrect: 'ざんねん！文化相対主義は「人権の基準は文化・社会によって違う」と考える立場だよ！', hintText: '文化によって基準が違うという考え', explanationDetail: '人権をめぐる議論：普遍的人権論「人権は文化を超えて全人類に共通」vs文化相対主義「各社会の文化・慣習の中で人権を定義すべき」。女性割礼・名誉殺人・体罰などを「文化」として正当化する主張への批判があります。国際人権法は普遍的人権を基本としつつも文化の多様性も考慮しています。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_13', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「ソーシャルジャスティス（社会正義）」とはどういう概念ですか？', choices: ['社会における公平・平等・人権の実現を目指す理念', '法律に従うこと', '多数決で決まること', '経済的平等を目指すこと'], correctIndex: 0, feedbackCorrect: 'せいかい！社会正義は公正な社会を目指す根本的な理念だよ！', feedbackIncorrect: 'ざんねん！ソーシャルジャスティスは社会の構造的な不平等・差別を解消し公正な社会を実現しようとする考えだよ！', hintText: '公正・平等な社会を目指す理念', explanationDetail: '社会正義（Social Justice）は個人の権利だけでなく、社会の構造的な不平等（貧困・差別・排除）を解消し、全員が公平な機会と尊厳を持てる社会を目指す概念。人種正義・ジェンダー平等・障がい者権利・経済格差是正などが含まれます。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_14', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'コモンズ（共有資源）の悲劇とはどういう問題ですか？', choices: ['みんなが共有する資源は、個人の利益優先で使いすぎて枯渇してしまう問題', 'みんなで使うと資源が増える問題', '政府が資源を独占する問題', '資源が均等に分配されない問題'], correctIndex: 0, feedbackCorrect: 'せいかい！共有資源の持続可能な管理は社会全体の課題だよ！', feedbackIncorrect: 'ざんねん！コモンズの悲劇は「みんなのもの」が自己利益優先で使われ資源が枯渇する問題だよ！', hintText: '共有資源の使いすぎ', explanationDetail: 'コモンズの悲劇（Tragedy of the Commons）はガレット・ハーディンが1968年に提唱。共有牧草地で各農民が「自分の牛だけ少し多く」と行動すると牧草地が荒廃するように、みんなが共有する資源（海の魚・空気・地下水）は個人の利益最大化行動で枯渇します。規制・コミュニティ管理・私有化などの解決策があります。', theme: 'values'),
  TaikuQuestion(id: 'tai_26_15', stage: LiteracyStage.stage26, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「功利主義」の考え方はどれですか？', choices: ['最大多数の最大幸福を目指すべきという考え方', '個人の権利が最優先という考え方', '神の命令に従うべきという考え方', '強い者が支配すべきという考え方'], correctIndex: 0, feedbackCorrect: 'せいかい！功利主義は現代の政策決定に大きな影響を与える倫理思想だよ！', feedbackIncorrect: 'ざんねん！功利主義は「最大多数の最大幸福」つまり最も多くの人の幸福を最大化することを善とする考え方だよ！', hintText: 'みんなの幸せの総量を最大にする', explanationDetail: '功利主義（Utilitarianism）はジェレミー・ベンサム・J.S.ミルが体系化した倫理思想。行為の善悪を「幸福・快楽の総量を増やすか」で判断します。コスト・ベネフィット分析や政策評価に応用されますが、少数者の権利が犠牲にされる可能性という批判もあります。', theme: 'values'),
];

const stage27Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_27_1', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '戦争を防ぐために作られた国際機関はどれですか？', choices: ['国際連合（国連）', '国際赤十字', 'オリンピック委員会', '世界銀行'], correctIndex: 0, feedbackCorrect: 'せいかい！国連は第二次世界大戦の反省から生まれた平和のための組織だよ！', feedbackIncorrect: 'ざんねん！第二次世界大戦後に世界平和と安全のために設立されたのが国際連合（国連）だよ！', hintText: '世界平和のための国際機関', explanationDetail: '国際連合（UN）は1945年、第二次世界大戦の反省から「戦争の惨禍から人類を救う」ために設立。193か国（2023年）が加盟し、安全保障理事会・総会・事務局などで構成されます。本部はニューヨーク。平和維持活動（PKO）・人道援助・開発支援などを行っています。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_2', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '日本国憲法で定められた「平和主義」とはどういうことですか？', choices: ['戦争を放棄して武力による解決はしないこと', '軍隊を持って国を守ること', '外国と同盟を結ぶこと', '核兵器を持つこと'], correctIndex: 0, feedbackCorrect: 'せいかい！日本国憲法第9条は戦争放棄を宣言した世界に誇れる条文だよ！', feedbackIncorrect: 'ざんねん！日本国憲法第9条は戦争放棄・戦力不保持・交戦権否認を定めているよ！', hintText: '戦争をしないという誓い', explanationDetail: '日本国憲法第9条は①戦争の放棄②戦力の不保持③交戦権の否認を定めています。1947年施行。この条文により日本は戦後78年以上、戦争に参加していません。一方、自衛隊の位置づけや集団的自衛権など憲法解釈をめぐる議論も続いています。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_3', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '核兵器の恐ろしさを世界に伝え続けることを何といいますか？', choices: ['被爆体験の継承（語り継ぎ）', '戦争の宣伝', '軍事教育', '歴史の否定'], correctIndex: 0, feedbackCorrect: 'せいかい！原爆・戦争の体験を次の世代に伝えることが平和を守るよ！', feedbackIncorrect: 'ざんねん！被爆者・戦争経験者の体験を次世代に伝え続けることが平和教育の根幹だよ！', hintText: '戦争の経験を次世代に伝える', explanationDetail: '1945年8月6日広島、9日長崎に原爆が投下され、合わせて約21万人以上が亡くなりました。被爆者（ヒバクシャ）の証言・遺構・資料が後世に伝えられています。広島平和記念資料館・長崎原爆資料館は年間多くの人が訪れます。「核なき世界」を訴え続けることが被爆国日本の使命です。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_4', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '「対話」で解決できない紛争に対して使う平和的な方法はどれですか？', choices: ['第三者による仲裁・調停', '武力攻撃', '無視する', '相手を孤立させる'], correctIndex: 0, feedbackCorrect: 'せいかい！第三者を交えた対話が平和的解決の鍵だよ！', feedbackIncorrect: 'ざんねん！直接話し合いが難しいときは中立的な第三者が仲介する調停・仲裁が有効だよ！', hintText: '中立な第三者が関わる', explanationDetail: '紛争解決の平和的手段：対話・交渉→調停（第三者が仲介）→仲裁（第三者が判断を下す）→国際司法裁判所への提訴。国連のPKO（平和維持活動）は停戦監視・選挙支援などを行います。暴力による解決は新たな憎しみを生み、根本解決になりません。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_5', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.practical, difficultyRank: 1, questionText: '世界で「子どもの兵士」が問題になっているのはなぜですか？', choices: ['子どもは教育を受ける権利があり、武力紛争に巻き込まれるべきでないから', '子どもは強いから', '子どもの方が安いから', '子どもは従順だから'], correctIndex: 0, feedbackCorrect: 'せいかい！子ども兵士は子どもの権利の重大な侵害だよ！', feedbackIncorrect: 'ざんねん！子どもは守られるべき存在であり、武力紛争への動員は重大な人権侵害だよ！', hintText: '子どもは守られるべき存在', explanationDetail: '世界では約25万人以上の子どもが武力紛争に兵士・使役として動員されていると推定されます（NGO Report）。ユニセフ・国連は子ども兵士の解放・社会復帰を支援しています。国際刑事裁判所（ICC）では子ども兵士の徴集は「戦争犯罪」として裁かれます。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_6', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '国際人道法（戦時国際法）の目的は何ですか？', choices: ['戦争中でも守るべき最低限のルールを定めて人々を保護すること', '戦争のやり方を促進すること', '勝者の権利を守ること', '武器の製造を規制すること'], correctIndex: 0, feedbackCorrect: 'せいかい！戦争中でも人道的な最低限のルールを守ることが重要だよ！', feedbackIncorrect: 'ざんねん！国際人道法はジュネーブ条約などで「戦争中でも傷病者・捕虜・民間人を保護する」ルールを定めているよ！', hintText: '戦争中の人道的ルール', explanationDetail: '国際人道法（IHL）はジュネーブ条約（1949年）・追加議定書などで構成。戦闘員と民間人の区別・傷病者・捕虜の保護・使用禁止兵器の規定などを定めます。国際赤十字委員会（ICRC）が普及・監視を担います。違反は戦争犯罪として国際刑事裁判所で裁かれます。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_7', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: 'ジェノサイドとはどういうことですか？', choices: ['特定の民族・宗教・人種集団を絶滅させようとする行為', '政府への反対運動', '移民政策', '領土の拡大'], correctIndex: 0, feedbackCorrect: 'せいかい！ジェノサイドは人類最大の罪のひとつとして国際法で禁止されているよ！', feedbackIncorrect: 'ざんねん！ジェノサイドは特定の民族・宗教・国籍グループを組織的に殺害・破壊しようとする行為だよ！', hintText: '特定グループの組織的な絶滅', explanationDetail: 'ジェノサイド（集団殺害）はホロコースト（ユダヤ人虐殺・600万人）・ルワンダ虐殺（1994年・100万人）などが歴史的事例。1948年にジェノサイド条約が採択され国際法で禁止されています。「Never Again（二度と繰り返すな）」という誓いと記憶の継承が重要です。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_8', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '「過渡的正義（移行期正義）」とはどういうことですか？', choices: ['紛争後の社会が過去の人権侵害に向き合い和解・復興を進めること', '戦争中の裁判制度', '勝者が敗者を裁くこと', '歴史を書き直すこと'], correctIndex: 0, feedbackCorrect: 'せいかい！過去と向き合うことが持続的な平和と和解の基盤になるよ！', feedbackIncorrect: 'ざんねん！移行期正義は紛争・独裁後の社会が過去の違反を調査・裁判・謝罪・補償で解決し和解する取り組みだよ！', hintText: '過去の人権侵害に向き合う', explanationDetail: '移行期正義（Transitional Justice）は真実和解委員会（南アフリカ）・国際戦犯法廷（旧ユーゴスラビア・ルワンダ）・被害者補償などの手段で、紛争後社会の和解と民主主義への移行を支援します。「知る権利・裁かれる権利・補償を受ける権利・再発防止」の4原則が基盤です。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_9', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '軍縮（ぐんしゅく）とはどういうことですか？', choices: ['各国が軍備・兵器を削減・制限すること', '軍隊の訓練を強化すること', '新しい兵器を開発すること', '同盟国を増やすこと'], correctIndex: 0, feedbackCorrect: 'せいかい！軍縮は世界平和と安全保障のための重要な取り組みだよ！', feedbackIncorrect: 'ざんねん！軍縮は国家間の協議で軍事力・兵器を削減・制限することだよ！', hintText: '兵器・軍備を減らす', explanationDetail: '軍縮（Disarmament）には核軍縮（核拡散防止条約NPT・核兵器禁止条約TPNW）・通常兵器規制（地雷禁止条約・クラスター爆弾禁止条約）などがあります。2017年に核兵器禁止条約が採択され、2021年発効。日本は唯一の被爆国ですが条約に署名していません。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_10', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.critical, difficultyRank: 2, questionText: '「平和構築」と「平和維持」の違いは何ですか？', choices: ['平和維持は停戦の監視、平和構築は紛争の根本原因を解決して持続的平和をつくること', '全く同じ意味', '平和構築は軍事活動、平和維持は外交活動', '平和維持は長期的、平和構築は短期的'], correctIndex: 0, feedbackCorrect: 'せいかい！持続的な平和には停戦だけでなく根本的な課題解決が必要だよ！', feedbackIncorrect: 'ざんねん！平和維持（停戦・秩序維持）と平和構築（制度・和解・開発で根本原因を解決）は違うアプローチだよ！', hintText: '止める vs 根本解決', explanationDetail: '平和の概念：①平和維持（Peacekeeping）：PKO派遣で停戦・秩序を維持②平和執行（Peace Enforcement）：武力行使で平和を回復③平和構築（Peacebuilding）：紛争の根本原因（貧困・差別・ガバナンス不全）を解決して持続的平和をつくる。最も困難で時間がかかるが最も重要なのが平和構築です。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_11', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「抑止論（核抑止）」の考え方はどういうものですか？', choices: ['核兵器を持つことで相互破壊の恐怖から攻撃を防げるという考え方', '核兵器を廃絶すれば平和になるという考え方', '通常兵器で戦争を防げるという考え方', '外交だけで平和を維持できるという考え方'], correctIndex: 0, feedbackCorrect: 'せいかい！核抑止論は冷戦時代から続く安全保障の根本的議論だよ！', feedbackIncorrect: 'ざんねん！核抑止は「核を使えば相互確証破壊（MAD）になる」という恐怖で攻撃を抑える考え方だよ！', hintText: '恐怖で攻撃を防ぐ', explanationDetail: '核抑止（Nuclear Deterrence）は「核攻撃すれば報復核攻撃で双方が壊滅する（MAD：相互確証破壊）という恐怖で戦争を防ぐ」理論。冷戦期の米ソ対立で生まれました。批判：偶発的核使用リスク・核拡散促進・被爆国の道義的立場から廃絶すべき。支持：現実の安全保障に機能している。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_12', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「構造的暴力」とはどういう概念ですか？', choices: ['貧困・差別・不平等など社会構造が人々の可能性を奪う間接的な暴力', '身体的な暴力', '言葉による暴力', '戦争による暴力'], correctIndex: 0, feedbackCorrect: 'せいかい！平和学者のヨハン・ガルトゥングが提唱した重要な概念だよ！', feedbackIncorrect: 'ざんねん！構造的暴力は社会の仕組みが特定の人々に不利益を与え、可能性・自由を奪う間接的な暴力だよ！', hintText: '社会の仕組みが可能性を奪う', explanationDetail: '平和学者ヨハン・ガルトゥングが提唱した「暴力の三角形」：直接的暴力（戦争・虐待）・構造的暴力（貧困・差別・不平等）・文化的暴力（差別を正当化するイデオロギー）。真の平和（積極的平和）は直接的暴力がないだけでなく、構造的暴力も存在しない状態を目指します。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_13', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「市民的不服従」とはどういう行為ですか？', choices: ['不当な法律・政策に対して非暴力的手段で抵抗する行為', '暴力的な革命', '法律を無視すること', '選挙に参加しないこと'], correctIndex: 0, feedbackCorrect: 'せいかい！ガンジーやキング牧師が実践した非暴力抵抗の重要な概念だよ！', feedbackIncorrect: 'ざんねん！市民的不服従は不正な権力・法律に対して非暴力的に抵抗する行為だよ！', hintText: '非暴力で不正に抵抗する', explanationDetail: '市民的不服従（Civil Disobedience）はヘンリー・ソローが提唱し、ガンジーの非暴力不服従運動（インド独立）・キング牧師の公民権運動（バス・ボイコット・座り込み）などで実践されました。「不正な法律には従わない」という道徳的権利を主張しつつ、法的責任を受け入れる点が特徴です。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_14', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「積極的平和主義」（日本政府の用語）が批判される理由はどれですか？', choices: ['軍事的関与の拡大につながる可能性があるという批判', '経済支援を増やしすぎるという批判', '外交活動が不足するという批判', '国連への貢献が減るという批判'], correctIndex: 0, feedbackCorrect: 'せいかい！平和主義の解釈をめぐる議論は民主主義社会で常に行われるよ！', feedbackIncorrect: 'ざんねん！日本政府の「積極的平和主義」には憲法9条との整合性・軍事的役割拡大への懸念が批判として挙げられるよ！', hintText: '軍事的関与が増えるという懸念', explanationDetail: '日本政府の「積極的平和主義」（2013年〜）は国際社会の平和・安定により積極的に貢献する方針。賛成：日本の国際的責任を果たす。批判：集団的自衛権容認（安保法制）・自衛隊の役割拡大が憲法9条の平和主義に反するという懸念。「積極的平和」はガルトゥングの概念（構造的暴力の除去）と異なります。', theme: 'values'),
  TaikuQuestion(id: 'tai_27_15', stage: LiteracyStage.stage27, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「人間の安全保障」とは何を守る概念ですか？', choices: ['国家ではなく個々の人間の生命・生活・尊厳を守ること', '国家の領土と主権を守ること', '軍事的安全を確保すること', '経済成長を守ること'], correctIndex: 0, feedbackCorrect: 'せいかい！人間の安全保障は国家中心の安全保障から個人中心へのパラダイム転換だよ！', feedbackIncorrect: 'ざんねん！人間の安全保障は「国家」ではなく「人間個人」の安全・生活・尊厳を守る概念だよ！', hintText: '国家ではなく人間一人ひとりを守る', explanationDetail: '人間の安全保障（Human Security）は1994年国連開発計画（UNDP）報告書で提唱。冷戦後、安全保障の主体を「国家」から「人間個人」に転換。貧困・飢餓・疾病・人権侵害・環境破壊などを個人への「脅威」として捉えます。日本は人間の安全保障の推進を外交政策の柱にしています。', theme: 'values'),
];

const stage28Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_28_1', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '絵の具で「赤」と「青」を混ぜると何色になりますか？', choices: ['むらさき', 'みどり', 'オレンジ', 'きいろ'], correctIndex: 0, feedbackCorrect: 'せいかい！赤と青を混ぜると紫になるよ！', feedbackIncorrect: 'ざんねん！赤と青を混ぜると紫色になるよ！', hintText: '赤＋青＝？', explanationDetail: '絵の具の混色：赤＋青＝紫、赤＋黄＝オレンジ、青＋黄＝緑。赤・青・黄は「三原色」で、この3色を混ぜると様々な色が作れます。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_2', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '絵の具で「赤」と「黄」を混ぜると何色になりますか？', choices: ['オレンジ', 'むらさき', 'みどり', 'ちゃいろ'], correctIndex: 0, feedbackCorrect: 'せいかい！赤と黄を混ぜるとオレンジ色になるよ！', feedbackIncorrect: 'ざんねん！赤と黄を混ぜるとオレンジ色になるよ！', hintText: '赤＋黄＝？', explanationDetail: '色の混ぜ方：赤＋黄＝オレンジ、青＋黄＝緑、赤＋青＝紫。絵を描くとき、混色を工夫することで自分だけの色が作れます。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_3', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '絵を描くとき、最初に行うのはどれですか？', choices: ['下書き（えんぴつで形を書く）', '色をぬる', '消しゴムで消す', 'ニスをぬる'], correctIndex: 0, feedbackCorrect: 'せいかい！まず鉛筆で下書きをしてから色をぬるよ！', feedbackIncorrect: 'ざんねん！最初に鉛筆で形を決める下書きをするよ！', hintText: '鉛筆で形を決める', explanationDetail: '絵の手順：①鉛筆で下書き②確認・修正③絵の具で色を塗る④仕上げ。下書きをすることで全体のバランスがとりやすくなります。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_4', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '白い絵の具を混ぜると色はどうなりますか？', choices: ['明るく（薄く）なる', '暗くなる', '変わらない', '黒くなる'], correctIndex: 0, feedbackCorrect: 'せいかい！白を混ぜると色が明るく薄くなるよ！', feedbackIncorrect: 'ざんねん！白い絵の具を混ぜると色が明るく淡くなるよ！', hintText: '白を加えると色が…', explanationDetail: '明度の調整：白を混ぜると明るく（明度が上がる）、黒を混ぜると暗く（明度が下がる）なります。赤＋白＝ピンク、青＋白＝水色になります。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_5', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「三角形」「四角形」「丸」を使って絵を作ることを何といいますか？', choices: ['形を使った構成', 'スケッチ', 'コラージュ', 'デッサン'], correctIndex: 0, feedbackCorrect: 'せいかい！形を組み合わせて絵や模様を作るよ！', feedbackIncorrect: 'ざんねん！三角・四角・丸などの形を組み合わせて絵や模様を作ることを「形を使った構成」というよ！', hintText: '図形で絵を作る', explanationDetail: '図形を使った構成は図工の基礎。三角・四角・丸などを組み合わせてロボット・家・動物などを表現できます。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_6', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「暖色（だんしょく）」とはどんな色ですか？', choices: ['赤・オレンジ・黄色など温かく感じる色', '青・水色・緑など涼しく感じる色', '白・黒・グレーなど色味のない色', '紫・茶色など落ち着いた色'], correctIndex: 0, feedbackCorrect: 'せいかい！暖色は温かい印象を与える色だよ！', feedbackIncorrect: 'ざんねん！暖色は赤・オレンジ・黄など炎や太陽のような温かいイメージの色だよ！', hintText: '温かいイメージの色', explanationDetail: '色の温度感：暖色（赤・オレンジ・黄）は温かみを感じ、寒色（青・水色）は涼しさを感じます。夕焼けは暖色、海や空は寒色が多いです。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_7', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '版画で紙に転写するとき、絵はどうなりますか？', choices: ['左右が反対（反転）になる', '上下が反対になる', '全く同じになる', '小さくなる'], correctIndex: 0, feedbackCorrect: 'せいかい！版画は左右が反転して写るよ！', feedbackIncorrect: 'ざんねん！版画は紙に転写すると左右が反対になるよ！だから版を彫るときは逆向きに彫る必要があるよ！', hintText: '鏡に映したように…', explanationDetail: '版画は彫った版にインクをつけて紙に押し付ける技法。転写すると左右が反転するので、文字や方向がある絵は逆向きに彫ります。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_8', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '粘土で作品を作るとき、接着が必要な部分はどうしますか？', choices: ['両方の面に傷をつけてから合わせる', 'そのままくっつける', '接着剤を使う', '乾かしてからくっつける'], correctIndex: 0, feedbackCorrect: 'せいかい！粘土は接合部を粗くしてしっかりくっつけるよ！', feedbackIncorrect: 'ざんねん！粘土を接合するときは両方の面に傷をつけ、溶かした粘土（どべ）を使ってくっつけるよ！', hintText: '両方の面を粗くして接合', explanationDetail: '粘土の接合法：①接合する両面を粗面にする②溶いた粘土（どべ）を塗る③合わせて押し付ける。これをしないと焼成後にひび割れたり外れたりします。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_9', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「遠近法（えんきんほう）」とはどういう描き方ですか？', choices: ['遠くのものを小さく、近くのものを大きく描く方法', '遠くのものを大きく描く方法', '全部同じ大きさで描く方法', '上から見た絵を描く方法'], correctIndex: 0, feedbackCorrect: 'せいかい！遠近法を使うと絵に奥行きが生まれるよ！', feedbackIncorrect: 'ざんねん！遠近法は遠くのものを小さく・近くのものを大きく描き、奥行きを表現する方法だよ！', hintText: '遠いものは小さく見える', explanationDetail: '遠近法（透視図法）は奥行きを平面に表現する技法。線遠近法（消失点に収束）と空気遠近法（遠くは薄くなる）があります。現代のアニメ背景でも使われます。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_10', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「コラージュ」とはどんな技法ですか？', choices: ['紙や写真などを切り貼りして作品を作る技法', '絵の具を指でぬる技法', '砂を使う技法', '消しゴムで描く技法'], correctIndex: 0, feedbackCorrect: 'せいかい！コラージュは様々な素材を切り貼りするアート技法だよ！', feedbackIncorrect: 'ざんねん！コラージュは雑誌・色紙・写真などを切り貼りして新しい作品を作る技法だよ！', hintText: '切り貼りして作る', explanationDetail: 'コラージュは新聞・雑誌・布・写真などを切り貼りして表現します。ピカソやブラックが始めたキュビスムで広まりました。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_11', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「補色（ほしょく）」とはどういう関係の色ですか？', choices: ['色相環で正反対に位置し、並べると互いを引き立て合う色', '同じ系統の色', '白に近い色', '混ぜると茶色になる色'], correctIndex: 0, feedbackCorrect: 'せいかい！補色を使うとコントラストが強調され、印象的な作品になるよ！', feedbackIncorrect: 'ざんねん！補色は色相環で正反対の位置にある色で、並べると互いを強調し合うよ！', hintText: '色相環で向かい合う色', explanationDetail: '補色の例：赤↔緑、青↔オレンジ、黄↔紫。補色を並べると視覚的コントラストが生まれます。印象派の画家は補色を活用して光の表現を豊かにしました。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_12', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「抽象画」と「具象画」の違いはどれですか？', choices: ['抽象画は形や色で感情を表し、具象画は実在するものをリアルに描く', '抽象画は風景画、具象画は人物画', '全く同じ', '抽象画は白黒、具象画はカラー'], correctIndex: 0, feedbackCorrect: 'せいかい！抽象と具象の違いを理解すると、美術作品の見方が広がるよ！', feedbackIncorrect: 'ざんねん！抽象画は形・色・線で感情や概念を表現し、具象画は実在する対象をそれと分かるように描くよ！', hintText: 'リアルか、感情表現か', explanationDetail: '具象画（具体的な対象を描く）vs抽象画（形・色・線のみで表現）。代表的抽象画家：カンディンスキー・モンドリアン。日本では岡本太郎が有名。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_13', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「デザイン」と「ファインアート（純粋芸術）」の違いはどれですか？', choices: ['デザインは目的・機能を重視し、ファインアートは表現・鑑賞を主目的とする', 'デザインは手書き、ファインアートはデジタル', '全く同じ意味', 'デザインは絵、ファインアートは彫刻'], correctIndex: 0, feedbackCorrect: 'せいかい！デザインと芸術は目的の違いで区別されるよ！', feedbackIncorrect: 'ざんねん！デザインは機能・目的を優先し、ファインアートは自己表現や鑑賞を主目的とするよ！', hintText: '機能重視か表現重視か', explanationDetail: 'デザイン：広告・製品・UI/UXなど機能・目的を優先。ファインアート：絵画・彫刻など美的価値を優先。バウハウス（ドイツ）がこの統合を体系化しました。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_14', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '美術館で作品を見るとき大切なことはどれですか？', choices: ['作者の意図や時代背景を考えながら鑑賞する', '素早く全部見る', '好きな作品だけを見る', '写真をできるだけ多く撮る'], correctIndex: 0, feedbackCorrect: 'せいかい！作品の背景を知ることで鑑賞がさらに深まるよ！', feedbackIncorrect: 'ざんねん！作品を深く味わうには、作者がいつ・なぜ・どんな気持ちで作ったかを考えることが大切だよ！', hintText: '作者の思いを想像する', explanationDetail: '美術鑑賞の深め方：①作者・時代・背景を調べる②色・形・構図を分析する③自分の感想と照らし合わせる④他の人の視点を聞く。', theme: 'art'),
  TaikuQuestion(id: 'tai_28_15', stage: LiteracyStage.stage28, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'ゴッホの「ひまわり」やモネの「睡蓮」のような絵画の流派を何といいますか？', choices: ['印象派（いんしょうは）', '写実主義', '超現実主義', 'ポップアート'], correctIndex: 0, feedbackCorrect: 'せいかい！印象派は光と色彩を大切にした革命的な芸術運動だよ！', feedbackIncorrect: 'ざんねん！モネ・ルノワール・ゴッホらが光と色彩の瞬間的な印象を表現した流派が印象派だよ！', hintText: '光の瞬間を描く画家たち', explanationDetail: '印象派は1860-1880年代にフランスで起きた芸術運動。モネ・ルノワール・ドガなどが中心。「その瞬間の光と色彩」を重視し、現代で最も愛される流派のひとつです。', theme: 'art'),
];

const stage29Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_29_1', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'はさみで紙を切るとき、一番大切なことはどれですか？', choices: ['刃先を人に向けない', '早く切る', '目を閉じて切る', '両手ではさみを持つ'], correctIndex: 0, feedbackCorrect: 'せいかい！はさみは刃先を人に向けないように気をつけよう！', feedbackIncorrect: 'ざんねん！はさみを使うとき一番大切なのは刃先を人に向けないことだよ！', hintText: '安全第一！刃先の向き', explanationDetail: 'はさみの安全な使い方：①刃先を人に向けない②渡すときは刃を閉じて持ち手を相手に向ける③走りながら使わない。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_2', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '紙粘土で作品を作った後、どうするとよいですか？', choices: ['よく乾かす', 'すぐ水につける', '熱いお湯で加熱する', 'そのままにする'], correctIndex: 0, feedbackCorrect: 'せいかい！紙粘土は乾かすとかたくなって完成するよ！', feedbackIncorrect: 'ざんねん！紙粘土は空気にさらして乾燥させると固まって完成するよ！', hintText: '乾かすと固まる', explanationDetail: '紙粘土は水分が蒸発することで固まります。薄いもので1〜2日、厚いもので3〜7日かかります。乾燥後に絵の具で色塗りできます。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_3', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '木を削ったり形を作ったりする作業を何といいますか？', choices: ['彫刻（ちょうこく）', '版画', 'スケッチ', 'コラージュ'], correctIndex: 0, feedbackCorrect: 'せいかい！木や石を削って形を作ることを彫刻というよ！', feedbackIncorrect: 'ざんねん！木や粘土・石を削ったり形を作ったりすることを彫刻というよ！', hintText: '木や石を削って形を作る', explanationDetail: '彫刻は三次元の立体作品を作る技術。有名な彫刻：ミケランジェロの「ダビデ像」・ロダンの「考える人」。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_4', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '工作でボンドが乾く前はどうしますか？', choices: ['動かさないようにそっと押さえる', 'すぐに動かす', '水をかける', 'ドライヤーで冷やす'], correctIndex: 0, feedbackCorrect: 'せいかい！ボンドが乾くまでしっかり固定しよう！', feedbackIncorrect: 'ざんねん！ボンドが乾く前に動かすとくっつかないよ！乾くまでそっと押さえておこう！', hintText: 'くっつくまで固定！', explanationDetail: '木工用ボンドが完全に乾くまで約24時間かかります。乾燥中は洗濯バサミなどで固定するとよいです。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_5', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「モビール」とはどんな作品ですか？', choices: ['糸やワイヤーでぶら下げてゆらゆら動く立体作品', '壁にかける絵', '床に置く彫刻', 'ノートに描く絵'], correctIndex: 0, feedbackCorrect: 'せいかい！モビールは空気の流れでゆらゆら動く動く彫刻だよ！', feedbackIncorrect: 'ざんねん！モビールは細い棒や糸でバランスをとってぶら下げ、動く立体作品だよ！', hintText: 'ぶら下がってゆれる', explanationDetail: 'モビールはアレクサンダー・カルダーが発明した動く彫刻。針金・糸・板でバランスをとり、空気の流れで動きます。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_6', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「彩度（さいど）」とはどういうことですか？', choices: ['色の鮮やかさの度合い', '色の明るさの度合い', '色の種類', '色の温度'], correctIndex: 0, feedbackCorrect: 'せいかい！彩度は色の鮮やかさを表すよ！', feedbackIncorrect: 'ざんねん！彩度は色の鮮やかさ・濃さの度合いのことだよ！', hintText: '色の鮮やかさ', explanationDetail: '色の三属性：①色相（色の種類）②明度（明るさ）③彩度（鮮やかさ）。絵の具に白や灰色を混ぜると彩度が下がります。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_7', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「テクスチャー」とはどういう意味ですか？', choices: ['表面の手触り・質感', '絵の色', '作品の大きさ', '絵のテーマ'], correctIndex: 0, feedbackCorrect: 'せいかい！テクスチャーは表面の質感・手触りのことだよ！', feedbackIncorrect: 'ざんねん！テクスチャーは作品の表面の質感（ざらざら、すべすべなど）のことだよ！', hintText: '表面の質感・手触り', explanationDetail: 'テクスチャー：実際に触れる「実際のテクスチャー」と、絵で視覚的に表現する「視覚的テクスチャー」があります。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_8', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '工作で「設計図」を描く目的は何ですか？', choices: ['完成のイメージを決めて材料や手順を考えるため', '先生に見せるため', '色を塗るため', '友達と競争するため'], correctIndex: 0, feedbackCorrect: 'せいかい！設計図を描くことで失敗を減らし、完成度が上がるよ！', feedbackIncorrect: 'ざんねん！設計図は完成イメージを決め、材料・手順を事前に考えるためにかくよ！', hintText: '完成前に計画を立てる', explanationDetail: '設計図の重要性：①完成イメージを明確にする②材料・道具をリストアップできる③手順の問題点を事前に発見できる。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_9', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「フロッタージュ」とはどんな技法ですか？', choices: ['凸凹した面に紙をあてて鉛筆でこする技法', '水と絵の具を流す技法', '紙を折りたたむ技法', '布を染める技法'], correctIndex: 0, feedbackCorrect: 'せいかい！フロッタージュは木の葉や硬貨の模様を写し取れるよ！', feedbackIncorrect: 'ざんねん！フロッタージュは凹凸のある面に紙をあて、鉛筆でこすって模様を写す技法だよ！', hintText: '葉や硬貨を紙でこする', explanationDetail: 'フロッタージュは木の葉・硬貨など凸凹のある素材の上に紙を置き、えんぴつでこすると模様が浮かび上がる技法です。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_10', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「シンメトリー（対称）」を使った作品の特徴はどれですか？', choices: ['左右（または上下）が同じ形になって、安定した美しさがある', '全部バラバラで動きがある', '色がたくさん使われている', 'とても複雑な模様がある'], correctIndex: 0, feedbackCorrect: 'せいかい！シンメトリーは安定感と均衡の美しさを生み出すよ！', feedbackIncorrect: 'ざんねん！シンメトリーは左右や上下が鏡のように同じ形になり、安定感の美しさを生む構図だよ！', hintText: '左右が鏡のように同じ', explanationDetail: 'シンメトリー（対称）：タージマハル・蝶の羽・雪の結晶など自然界にも多い。非対称は動き・緊張感を生みます。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_11', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「バウハウス」とはどんな学校・芸術運動ですか？', choices: ['芸術と工業技術を統合した20世紀ドイツの学校・デザイン運動', '日本の伝統工芸学校', '印象派の絵画グループ', 'イタリアのルネサンス運動'], correctIndex: 0, feedbackCorrect: 'せいかい！バウハウスのデザイン思想は現代のデザインの基礎になっているよ！', feedbackIncorrect: 'ざんねん！バウハウスは1919年ドイツに設立された、芸術・工芸・建築・工業デザインを統合した学校だよ！', hintText: '芸術と工業を融合させた学校', explanationDetail: 'バウハウスはワルター・グロピウスが1919年設立。「芸術と技術の統合」を掲げ、現代のグラフィックデザイン・建築・家具デザインに大きな影響を与えました。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_12', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「パブリックアート」とはどういう作品ですか？', choices: ['駅・広場・公園など公共空間に設置されたアート作品', '美術館だけに置かれる作品', '個人が所有する作品', 'デジタルだけのアート'], correctIndex: 0, feedbackCorrect: 'せいかい！パブリックアートは街に溶け込んだみんなのアートだよ！', feedbackIncorrect: 'ざんねん！パブリックアートは駅・広場・病院など公共空間に設置され、多くの人が無料で見られるアート作品だよ！', hintText: '公共の場に設置されたアート', explanationDetail: '岡本太郎の「太陽の塔」・草間彌生の水玉作品が有名なパブリックアートの例です。地域のアイデンティティを表現します。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_13', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「著作権」と図工・美術の関係はどれですか？', choices: ['他人の作品をそのままコピーして使うことは著作権侵害になる', '美術作品には著作権はない', '学校で使う分には何でもコピーOK', '古い作品は全て自由に使える'], correctIndex: 0, feedbackCorrect: 'せいかい！他人の作品を許可なく使うことは著作権侵害になるよ！', feedbackIncorrect: 'ざんねん！美術作品にも著作権があり、作者の許可なくコピー・転載することは違法だよ！', hintText: '作品も作者の権利がある', explanationDetail: '著作権は作品を作った瞬間に自動で発生し、原則として死後70年間保護されます。インターネットの画像を無断使用することも著作権侵害になります。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_14', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「インスタレーション」とはどんなアートですか？', choices: ['空間全体を作品として体験する芸術形式', '額縁に入れた絵画', '写真を集めたアルバム', '音楽の演奏'], correctIndex: 0, feedbackCorrect: 'せいかい！インスタレーションは空間そのものを作品にする現代アートだよ！', feedbackIncorrect: 'ざんねん！インスタレーションは特定の場所・空間全体を使い、見る人が体験するアート形式だよ！', hintText: '空間全体が作品', explanationDetail: 'インスタレーションは1960年代以降に発展した現代アート。草間彌生の「無限の鏡の部屋」・チームラボのデジタルアートが有名です。', theme: 'art'),
  TaikuQuestion(id: 'tai_29_15', stage: LiteracyStage.stage29, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '図工・美術で「批評」する目的はどれですか？', choices: ['作品の良さや課題を言葉にして理解を深め、次の制作に生かすため', '友達の作品を悪く言うため', '先生を批判するため', '点数をつけるため'], correctIndex: 0, feedbackCorrect: 'せいかい！批評は作品を深く理解し、自分の表現を豊かにするために大切だよ！', feedbackIncorrect: 'ざんねん！美術批評は作品の優れた点・改善点を言語化し、理解と表現力を深めるために行うよ！', hintText: '作品をより深く理解するため', explanationDetail: '美術批評の手順：①記述（何が見えるか）②分析（要素の関係）③解釈（何を表しているか）④評価（どれだけ成功しているか）。', theme: 'art'),
];

const stage30Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_30_1', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '音楽で「ド・レ・ミ・ファ・ソ・ラ・シ」は何個の音がありますか？', choices: ['7つ', '5つ', '8つ', '10つ'], correctIndex: 0, feedbackCorrect: 'せいかい！ドレミは7つの音でできているよ！', feedbackIncorrect: 'ざんねん！ドレミファソラシは7つの音だよ！', hintText: 'ド・レ・ミ・ファ・ソ・ラ・シを数えよう', explanationDetail: 'ドレミファソラシは7音（音名）で1オクターブを構成します。次のドは1オクターブ上の音。イタリア語の音名で、日本語ではハニホヘトイロと呼びます。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_2', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '音楽で「♩」（四分音符）はどのくらいの長さの音ですか？', choices: ['1拍', '2拍', '半拍', '4拍'], correctIndex: 0, feedbackCorrect: 'せいかい！四分音符は1拍（ひとつ）の長さだよ！', feedbackIncorrect: 'ざんねん！四分音符（♩）は1拍の長さの音符だよ！', hintText: '「いち」とかぞえる長さ', explanationDetail: '音符の長さ：全音符（○）＝4拍、二分音符（𝅗𝅥）＝2拍、四分音符（♩）＝1拍、八分音符（♪）＝半拍。4分の4拍子は1小節に四分音符が4つ入ります。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_3', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「リズム」とはどういうものですか？', choices: ['音の長さや強さが規則的に繰り返されるパターン', '音の高さ', '音の大きさ', '音の色'], correctIndex: 0, feedbackCorrect: 'せいかい！リズムは音のパターンだよ！タン・タン・タン…って感じ！', feedbackIncorrect: 'ざんねん！リズムは音の長さや強さが規則的に繰り返されるパターンのことだよ！', hintText: '音のパターン・繰り返し', explanationDetail: 'リズム（Rhythm）は音楽の基本要素のひとつ。長い音・短い音・強い拍・弱い拍が組み合わさって生まれます。心臓の鼓動も一種のリズムです。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_4', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '音楽の授業でよく使う、音の高さを出す楽器はどれですか？', choices: ['鍵盤ハーモニカ（ピアニカ）', '太鼓', 'カスタネット', 'タンバリン'], correctIndex: 0, feedbackCorrect: 'せいかい！鍵盤ハーモニカは息を吹きながら鍵盤を押して音を出すよ！', feedbackIncorrect: 'ざんねん！鍵盤ハーモニカ（ピアニカ）は鍵盤と息で音の高さを変えられる楽器だよ！', hintText: '鍵盤を押して息を吹く楽器', explanationDetail: '鍵盤ハーモニカはリード楽器の一種で、鍵盤を押しながら息を吹き込んで音を出します。メロディーを演奏できます。小学校低学年でよく使われます。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_5', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '歌を歌うとき、体のどの部分を一番大切に使いますか？', choices: ['お腹（腹式呼吸）', '手', '足', '目'], correctIndex: 0, feedbackCorrect: 'せいかい！歌うときはお腹を使った腹式呼吸が大切だよ！', feedbackIncorrect: 'ざんねん！歌うときはお腹から声を出す腹式呼吸が大切だよ！', hintText: 'お腹から声を出す', explanationDetail: '腹式呼吸：お腹を膨らませながら息を吸い、お腹を締めながら息を出す呼吸法。大きく安定した声が出ます。歌手・声優・吹奏楽器奏者全員が使う基本技術です。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_6', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「テンポ」とはどういうことですか？', choices: ['音楽の速さ', '音楽の大きさ', '音楽の高さ', '音楽の長さ'], correctIndex: 0, feedbackCorrect: 'せいかい！テンポは音楽の速さのことだよ！', feedbackIncorrect: 'ざんねん！テンポ（Tempo）は音楽の速さ・進む速度のことだよ！', hintText: '音楽の速さ', explanationDetail: 'テンポの用語：Largo（ラルゴ：とても遅く）、Andante（アンダンテ：歩くような速さ）、Moderato（モデラート：中ぐらい）、Allegro（アレグロ：速く）、Presto（プレスト：とても速く）。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_7', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「強弱記号」でpの意味はどれですか？', choices: ['ピアノ（弱く）', 'フォルテ（強く）', '普通の強さ', 'とても強く'], correctIndex: 0, feedbackCorrect: 'せいかい！pはピアノで弱く、fはフォルテで強くという意味だよ！', feedbackIncorrect: 'ざんねん！p（ピアノ）は弱く演奏するという意味だよ！f（フォルテ）が強くだよ！', hintText: 'pはピアノ＝？', explanationDetail: '強弱記号：pp（ピアニッシモ：とても弱く）、p（ピアノ：弱く）、mp（メゾピアノ：やや弱く）、mf（メゾフォルテ：やや強く）、f（フォルテ：強く）、ff（フォルティッシモ：とても強く）。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_8', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「音階（おんかい）」とはどういうものですか？', choices: ['低い音から高い音へ順番に並べた音の集まり', '同じ音を繰り返すこと', '音の大きさのこと', '歌詞のこと'], correctIndex: 0, feedbackCorrect: 'せいかい！音階は音を順番に並べたものだよ！', feedbackIncorrect: 'ざんねん！音階は音を低いものから高いものへ（または逆）順に並べたものだよ！', hintText: '低い音から高い音へ順番に', explanationDetail: '主な音階：長音階（明るい響き）・短音階（悲しい響き）・日本の音階（ヨナ抜き音階など）・ブルース音階。ドレミファソラシドは長音階の代表例です。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_9', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「合唱（がっしょう）」とはどういうことですか？', choices: ['複数の人が声を合わせて歌うこと', '一人で歌うこと', '楽器だけで演奏すること', '音楽を聴くこと'], correctIndex: 0, feedbackCorrect: 'せいかい！合唱はみんなで声を合わせて歌う素晴らしい表現だよ！', feedbackIncorrect: 'ざんねん！合唱は複数の人が声を合わせて歌うことだよ！ソロ（独唱）と区別しよう！', hintText: 'みんなで声を合わせる', explanationDetail: '合唱の形式：ユニゾン（全員同じ音）、二部合唱（2つのパート）、三部合唱・四部合唱。ソプラノ（高音域）、アルト（中低音域）、テノール・バス（男声）に分かれます。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_10', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「リコーダー」を正しく吹くコツはどれですか？', choices: ['「トゥ」と舌でタンギングしながら吹く', '思い切り強く吹く', '指を全部おさえない', '立って演奏する'], correctIndex: 0, feedbackCorrect: 'せいかい！タンギングで一つ一つの音をはっきり出そう！', feedbackIncorrect: 'ざんねん！リコーダーは「トゥ」と舌を使うタンギングで音をはっきり区切って演奏するよ！', hintText: '舌を使ってタンギング', explanationDetail: 'リコーダーのコツ：①優しい息（強く吹くと音が割れる）②タンギング（舌で音を区切る）③穴をしっかりふさぐ④「Tu/Du」の発音で吹く。ソプラノリコーダーは小学校で最もよく使われる楽器のひとつです。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_11', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「和音（わおん）」とはどういうものですか？', choices: ['2つ以上の音が同時に鳴る音の組み合わせ', '同じ音が2回鳴ること', 'メロディーのこと', '歌詞のこと'], correctIndex: 0, feedbackCorrect: 'せいかい！和音は複数の音が重なって豊かな響きを作るよ！', feedbackIncorrect: 'ざんねん！和音（コード）は2つ以上の音が同時に鳴る音の組み合わせだよ！', hintText: '複数の音が同時に鳴る', explanationDetail: '和音（コード）の基本：三和音はド・ミ・ソのように3つの音で構成。長三和音（明るい）・短三和音（暗い）がある。C・Am・F・Gの4コードで多くのポップソングが演奏できます。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_12', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「メロディー」「ハーモニー」「リズム」は音楽の何と呼ばれていますか？', choices: ['音楽の三要素', 'コードの三種類', '楽器の三分類', '歌の三つの声'], correctIndex: 0, feedbackCorrect: 'せいかい！メロディー・ハーモニー・リズムは音楽の三要素だよ！', feedbackIncorrect: 'ざんねん！メロディー（旋律）・ハーモニー（和声）・リズムは「音楽の三要素」といわれているよ！', hintText: '音楽を作る3つの基本', explanationDetail: '音楽の三要素：①メロディー（旋律）：音の高低の流れ②ハーモニー（和声）：複数の音の響き③リズム：音の時間的パターン。この3つが組み合わさって音楽が生まれます。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_13', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「ベートーベン」が作った有名な交響曲はどれですか？', choices: ['第九（歓喜の歌）', '運命（正式名は交響曲第5番）のみ', '白鳥の湖', 'ボレロ'], correctIndex: 0, feedbackCorrect: 'せいかい！第九（交響曲第9番）の第4楽章「歓喜の歌」は世界中で愛されているよ！', feedbackIncorrect: 'ざんねん！ベートーベンの交響曲第9番、通称「第九」の「歓喜の歌」は世界で最も有名な合唱曲のひとつだよ！', hintText: '大晦日にも演奏される有名な曲', explanationDetail: 'ベートーベン（1770-1827）：交響曲9番（第九）・交響曲5番（運命）・月光ソナタなどを作曲。聴覚を失っても作曲を続けた。「第九」はEU（欧州連合）の賛歌にも採用されています。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_14', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '音楽で「転調（てんちょう）」とはどういうことですか？', choices: ['曲の途中で調（キー）が変わること', 'テンポが変わること', '楽器が変わること', '歌詞が変わること'], correctIndex: 0, feedbackCorrect: 'せいかい！転調は曲に変化をもたらす重要な技法だよ！', feedbackIncorrect: 'ざんねん！転調は曲の途中でキー（調）が変わることで、曲に変化や盛り上がりをもたらすよ！', hintText: '曲の途中でキーが変わる', explanationDetail: '転調（Modulation）は曲の途中で調が変わること。例：Cメジャーからフォルテに転調すると曲が盛り上がります。J-POPでよくサビ前に半音上に転調する技法（キーチェンジ）が使われます。', theme: 'music'),
  TaikuQuestion(id: 'tai_30_15', stage: LiteracyStage.stage30, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「箏（こと）」は日本の伝統楽器ですが、弦は何本ありますか？', choices: ['13本', '6本', '8本', '20本'], correctIndex: 0, feedbackCorrect: 'せいかい！箏は13本の弦で奏でる日本の伝統楽器だよ！', feedbackIncorrect: 'ざんねん！箏（こと）は13本の弦を持つ日本の伝統的な弦楽器だよ！', hintText: '十三弦の楽器', explanationDetail: '箏（こと）は13本の弦を持つ日本の伝統弦楽器。弦に「柱（じ）」を置いて音の高さを調整し、爪（つめ）で弾きます。「さくらさくら」などの日本の伝統曲に使われます。現代では17弦・20弦箏もあります。', theme: 'music'),
];

const stage31Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_31_1', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'ピアノの鍵盤（けんばん）で白い鍵盤の数はどれに近いですか？', choices: ['52個', '36個', '88個', '12個'], correctIndex: 0, feedbackCorrect: 'せいかい！ピアノの白鍵は52個、全部で88鍵あるよ！', feedbackIncorrect: 'ざんねん！標準的なピアノは白鍵52個・黒鍵36個、合計88鍵あるよ！', hintText: '白い鍵盤は50個以上', explanationDetail: 'スタンダードピアノは88鍵（白52、黒36）。7オクターブ以上の音域をカバー。1709年イタリアのクリストフォリが発明。「ピアノ」はイタリア語のpianoforte（弱く-強く）が語源。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_2', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'バイオリンの弦は何本ありますか？', choices: ['4本', '6本', '3本', '8本'], correctIndex: 0, feedbackCorrect: 'せいかい！バイオリンは4本の弦を弓で弾く楽器だよ！', feedbackIncorrect: 'ざんねん！バイオリンの弦は4本（G・D・A・E）だよ！', hintText: '弓で弾く弦楽器', explanationDetail: 'バイオリンは4本の弦（G・D・A・E）を弓でこすって音を出す弦楽器。オーケストラで最も多くの奏者がいる楽器。弦楽四重奏はバイオリン2・ビオラ1・チェロ1で構成されます。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_3', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'トランペットはどんな楽器ですか？', choices: ['息を吹き込んで金属の管から音を出す管楽器', '弦を弾く楽器', 'たたいて音を出す楽器', '鍵盤を押す楽器'], correctIndex: 0, feedbackCorrect: 'せいかい！トランペットは金管楽器だよ！力強い音が出るよ！', feedbackIncorrect: 'ざんねん！トランペットは金属の管に息を吹き込み、唇の振動で音を出す金管楽器だよ！', hintText: '金属の管に息を吹く', explanationDetail: '金管楽器：トランペット・ホルン・トロンボーン・チューバなど。唇を振動させて音を出します。木管楽器（フルート・クラリネット・オーボエ）は主にリードや息の流れで音を出します。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_4', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「打楽器（だがっき）」とはどんな楽器ですか？', choices: ['たたいたり振ったりして音を出す楽器', '息で音を出す楽器', '弦をはじく楽器', '鍵盤を押す楽器'], correctIndex: 0, feedbackCorrect: 'せいかい！打楽器はたたいたり振ったりするリズム楽器だよ！', feedbackIncorrect: 'ざんねん！打楽器はたたいたり振ったりして音を出す楽器で、太鼓・シンバル・マラカスなどがあるよ！', hintText: 'たたいて音を出す', explanationDetail: '打楽器の種類：①有音程打楽器（ティンパニ・マリンバ・鉄琴）②無音程打楽器（バスドラム・スネアドラム・シンバル）。リズムを担当しオーケストラに欠かせません。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_5', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '日本の伝統楽器「太鼓（たいこ）」はどんな楽器ですか？', choices: ['皮を張った胴体をばちでたたく打楽器', '弦をはじく楽器', '息を吹く楽器', '鍵盤を押す楽器'], correctIndex: 0, feedbackCorrect: 'せいかい！和太鼓は日本の伝統的な打楽器で迫力ある音がするよ！', feedbackIncorrect: 'ざんねん！太鼓は皮を張った胴体をばちでたたく打楽器だよ！', hintText: 'ばちでたたく和楽器', explanationDetail: '和太鼓の種類：長胴太鼓・桶胴太鼓・締め太鼓など。祭りや芸能・神社仏閣での行事に使われます。現代では「鼓童」など国際的に活躍する太鼓集団も多いです。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_6', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「オーケストラ」はどのように楽器が配置されていますか？', choices: ['指揮者を中心に弦・木管・金管・打楽器が配置される', '全員バラバラに座る', '歌手だけが並ぶ', 'ピアノだけが並ぶ'], correctIndex: 0, feedbackCorrect: 'せいかい！オーケストラは指揮者を中心に各楽器群が配置されているよ！', feedbackIncorrect: 'ざんねん！オーケストラは指揮者の前に弦楽器が中心、後方に木管・金管・打楽器が配置されるよ！', hintText: '指揮者を中心に楽器が並ぶ', explanationDetail: 'オーケストラの配置：指揮者の前→第1バイオリン（左）・第2バイオリン（右）・ビオラ・チェロ→中列：木管楽器→後列：金管楽器→最後列：打楽器。指揮者は全体を統率します。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_7', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「長調（ちょうちょう）」と「短調（たんちょう）」の違いはどれですか？', choices: ['長調は明るく、短調は暗い響きがする', '長調は速く、短調は遅い', '長調は大きく、短調は小さい', '全く同じ'], correctIndex: 0, feedbackCorrect: 'せいかい！長調は明るく、短調は暗い・悲しい響きが特徴だよ！', feedbackIncorrect: 'ざんねん！長調（メジャー）は明るく陽気、短調（マイナー）は暗く悲しい響きが特徴だよ！', hintText: '明るいか暗いか', explanationDetail: '長調（メジャーキー）：ハッピーバースデー・ジングルベルなど明るい曲。短調（マイナーキー）：暗く悲しい・神秘的な曲。同じメロディーでも長調・短調を変えるだけで全く異なる印象になります。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_8', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「世界音楽（ワールドミュージック）」とはどういうものですか？', choices: ['世界各地の伝統音楽・民族音楽', 'クラシック音楽だけ', 'ポップスだけ', '日本の音楽だけ'], correctIndex: 0, feedbackCorrect: 'せいかい！世界には様々な文化の音楽があって多様性が豊かだよ！', feedbackIncorrect: 'ざんねん！ワールドミュージックはアフリカ・アジア・南米など世界各地の伝統音楽・民族音楽のことだよ！', hintText: '世界各地の伝統・民族音楽', explanationDetail: '世界の代表的な音楽：アフリカ（ポリリズム）・インド（ラーガ）・アラブ（マカーム）・沖縄（三線・琉球音楽）・ブラジル（サンバ・ボサノバ）。多様な文化の音楽に触れることで視野が広がります。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_9', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「即興演奏（そっきょうえんそう）」とはどういうことですか？', choices: ['楽譜なしでその場で自由に演奏すること', '楽譜を見て演奏すること', '録音を聴くこと', '友達と合奏すること'], correctIndex: 0, feedbackCorrect: 'せいかい！即興演奏は音楽を自由に創り出すことだよ！', feedbackIncorrect: 'ざんねん！即興演奏（インプロビゼーション）は楽譜なしでその場で自由に音楽を作り演奏することだよ！', hintText: '楽譜なし、その場で演奏', explanationDetail: '即興演奏はジャズの基本技術。決まったコード進行の上に自由にメロディーを乗せます。日本の雅楽・インドのラーガ・フラメンコなど世界の伝統音楽にも即興の要素があります。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_10', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '音楽で「強弱の変化」を効果的に使う目的はどれですか？', choices: ['曲に表情や感情の起伏をつけるため', '大きな音を出すため', '速く演奏するため', '楽器を傷めないため'], correctIndex: 0, feedbackCorrect: 'せいかい！強弱の変化で曲に豊かな表情が生まれるよ！', feedbackIncorrect: 'ざんねん！強弱（ダイナミクス）の変化は曲に感情・表情・物語性をもたらすために使うよ！', hintText: '曲に感情・表情をつける', explanationDetail: '音楽の表現技術：強弱（ダイナミクス）・テンポ変化（アッチェレランド：加速、リタルダンド：減速）・アーティキュレーション（スタッカート・レガート）を組み合わせて感情を表現します。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_11', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「ジャズ（Jazz）」はどこの国で生まれた音楽ですか？', choices: ['アメリカ合衆国（ニューオーリンズ）', 'フランス', 'イタリア', '日本'], correctIndex: 0, feedbackCorrect: 'せいかい！ジャズはアメリカのニューオーリンズでアフリカ系アメリカ人が生み出した音楽だよ！', feedbackIncorrect: 'ざんねん！ジャズは19世紀末〜20世紀初頭にアメリカのニューオーリンズでアフリカ系アメリカ人が創り出した音楽だよ！', hintText: 'アメリカ南部で生まれた', explanationDetail: 'ジャズはアフリカのリズム・ブルース・ラグタイム・ヨーロッパのハーモニーが融合して生まれました。即興演奏が特徴。マイルス・デイビス・チャーリー・パーカーが有名。世界中の音楽に影響を与えています。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_12', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「音楽著作権（JASRAC等）」とはどういうしくみですか？', choices: ['作曲者・作詞者の曲を使うとき使用料を払い権利者に分配するしくみ', '音楽を無料で使えるしくみ', '音楽を学校だけで使うしくみ', '演奏者が曲を独占するしくみ'], correctIndex: 0, feedbackCorrect: 'せいかい！著作権料は音楽家の創作活動を支える大切な仕組みだよ！', feedbackIncorrect: 'ざんねん！JASRACなどの著作権管理団体は、曲の使用料を集めて作曲者・作詞者に適切に分配するしくみだよ！', hintText: '作曲家・作詞家の権利を守る', explanationDetail: 'JASRAC（日本音楽著作権協会）は著作権管理団体。CDの販売・カラオケ・コンサート・テレビ放送で曲を使うたびに著作権料が発生し、作曲家・作詞家に支払われます。著作権は死後70年間保護されます。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_13', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「交響曲（こうきょうきょく）」は通常何楽章から構成されますか？', choices: ['4楽章', '1楽章', '2楽章', '10楽章'], correctIndex: 0, feedbackCorrect: 'せいかい！交響曲は通常4楽章で構成されるよ！', feedbackIncorrect: 'ざんねん！交響曲（シンフォニー）は通常4つの楽章から構成されるよ！', hintText: '4つのセクションがある', explanationDetail: '交響曲の基本構成：第1楽章（速い・ソナタ形式）、第2楽章（遅い・叙情的）、第3楽章（舞踊的・メヌエット等）、第4楽章（速い・フィナーレ）。ハイドン・モーツァルト・ベートーベンが交響曲形式を完成させました。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_14', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '音楽が心身に与える効果として正しいものはどれですか？', choices: ['ストレス軽減・集中力向上・感情表現など心身に良い影響がある', '音楽は心身に影響しない', '音楽は耳に悪い', '激しい音楽だけが体に良い'], correctIndex: 0, feedbackCorrect: 'せいかい！音楽は心身に様々な良い効果をもたらすよ！', feedbackIncorrect: 'ざんねん！音楽にはストレス軽減・集中力向上・感情表現・コミュニケーション促進などの効果があるよ！', hintText: '心身に良い影響がある', explanationDetail: '音楽療法（ミュージックセラピー）：音楽を使って心身の健康を促進する医療・福祉の技術。認知症・うつ・不安障がいの改善に効果があります。モーツァルト効果（クラシックで集中力向上）は研究でも支持されています。', theme: 'music'),
  TaikuQuestion(id: 'tai_31_15', stage: LiteracyStage.stage31, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「雅楽（ががく）」とはどういう音楽ですか？', choices: ['古代から伝わる日本の宮廷音楽・舞踊', 'J-POPの一種', '現代の日本のロック', '沖縄の民謡'], correctIndex: 0, feedbackCorrect: 'せいかい！雅楽は千年以上の歴史を持つ日本の宮廷音楽だよ！', feedbackIncorrect: 'ざんねん！雅楽は古代から伝わる日本の宮廷音楽・儀式音楽で、舞楽（まいがく）・管弦（かんげん）などがあるよ！', hintText: '日本の古代宮廷音楽', explanationDetail: '雅楽は奈良時代（8世紀）から伝わる日本の宮廷音楽・舞踊。楽器：笙（しょう）・篳篥（ひちりき）・龍笛（りゅうてき）・琵琶・琴。ユネスコ無形文化遺産に登録。宮内庁式部職楽部が現代も継承しています。', theme: 'music'),
];

const stage32Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_32_1', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '野菜を切るとき、指を守るための持ち方を何といいますか？', choices: ['ねこの手', 'グーの手', 'パーの手', 'ピースの手'], correctIndex: 0, feedbackCorrect: 'せいかい！指を丸めてねこの手にして切ると安全だよ！', feedbackIncorrect: 'ざんねん！指を曲げてねこのようにした「ねこの手」で食材を押さえると安全に切れるよ！', hintText: 'にゃー、の手の形', explanationDetail: 'ねこの手：指の先を少し曲げて関節で食材を押さえる方法。指の先が刃から守られます。包丁は刃を下に向けて持ち、切るときは刃を前に押しながら引く動作で切ります。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_2', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'ご飯（お米）を炊くとき、必要なものはどれですか？', choices: ['水とお米', '牛乳とお米', 'ジュースとお米', 'お米だけ'], correctIndex: 0, feedbackCorrect: 'せいかい！お米と水を加熱するとご飯が炊けるよ！', feedbackIncorrect: 'ざんねん！ご飯を炊くにはお米と水（それを加熱する器具）が必要だよ！', hintText: 'お米に何を加える？', explanationDetail: 'ご飯の炊き方：①米を量る②洗う③水を加える（米の約1.2倍）④炊飯器で炊く。炊飯器なら約30〜60分。鍋でも炊けます。お米の主成分はデンプンで、加熱すると消化しやすい形に変わります。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_3', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「五大栄養素」のうち体を動かすエネルギー源になるのはどれですか？', choices: ['炭水化物・脂質・タンパク質', 'ビタミン・ミネラルだけ', '水だけ', '食物繊維だけ'], correctIndex: 0, feedbackCorrect: 'せいかい！炭水化物・脂質・タンパク質がエネルギー源だよ！', feedbackIncorrect: 'ざんねん！炭水化物・脂質・タンパク質の3つがエネルギー（熱量）を生み出す栄養素だよ！', hintText: 'ご飯・油・肉が含む栄養', explanationDetail: '五大栄養素：①炭水化物（エネルギー源）②脂質（エネルギー源・細胞膜）③タンパク質（体の材料・エネルギー）④ビタミン（体の調節）⑤ミネラル（骨・血液の材料）。バランスよく食べることが大切。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_4', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '食器を洗うとき、一番先に洗うものはどれですか？', choices: ['コップやグラス', 'フライパン', '油のついた皿', 'まな板'], correctIndex: 0, feedbackCorrect: 'せいかい！汚れが少ないコップから洗い始めると効率よく洗えるよ！', feedbackIncorrect: 'ざんねん！食器洗いは汚れが少ないものから洗い始めよう。コップ→皿→鍋の順が基本だよ！', hintText: '汚れが少ないものから洗う', explanationDetail: '食器の洗い方の順番：①コップ・グラス（汚れが少ない）②茶碗・皿③油物・フライパン。油で汚れた物を先に洗うとスポンジ全体に油が広がります。油はお湯（温水）で落としやすくなります。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_5', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '食中毒（しょくちゅうどく）を防ぐため一番大切なことはどれですか？', choices: ['手をよく洗う・食材の管理・加熱を徹底する', '早く食べる', '冷たいものを食べない', '甘いものを食べない'], correctIndex: 0, feedbackCorrect: 'せいかい！手洗い・温度管理・十分な加熱が食中毒を防ぐ3つの柱だよ！', feedbackIncorrect: 'ざんねん！食中毒予防の基本は「手洗い（清潔）・冷蔵保存（温度管理）・十分な加熱」だよ！', hintText: '手洗い・温度・加熱', explanationDetail: '食中毒予防の原則：①菌をつけない（手洗い・調理器具の清潔）②菌を増やさない（冷蔵・冷凍保存）③菌を殺す（75℃以上1分以上の加熱）。夏場は特に食品の保存に注意が必要です。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_6', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「旬（しゅん）」の食材を食べることのよさはどれですか？', choices: ['一番おいしく、栄養価が高く、安く手に入りやすい', '一年中同じ値段で買える', '旬は関係ない', '輸入品の方が良い'], correctIndex: 0, feedbackCorrect: 'せいかい！旬の食材はおいしさ・栄養・値段の全てで優れているよ！', feedbackIncorrect: 'ざんねん！旬の食材はその時期に最もおいしく、栄養価が高く、旬以外より安く手に入りやすいよ！', hintText: '旬は一番おいしい時期', explanationDetail: '旬（しゅん）は食材が最もよく育ち、おいしくなる時期。例：春はタケノコ・菜の花、夏はトマト・きゅうり、秋はサンマ・きのこ、冬はほうれん草・ブリ。地産地消（地元の食材）も旬を活かします。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_7', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「一汁三菜（いちじゅうさんさい）」とはどういう食事の形ですか？', choices: ['汁物1品と、おかず3品、ご飯の和食の基本スタイル', '一つの料理に3種の食材', 'お菓子3種と飲み物', 'スープ3杯の食事'], correctIndex: 0, feedbackCorrect: 'せいかい！一汁三菜は日本の伝統的な栄養バランスの取れた食事スタイルだよ！', feedbackIncorrect: 'ざんねん！一汁三菜はご飯＋汁物（みそ汁等）＋主菜（肉・魚）＋副菜2品という和食の基本スタイルだよ！', hintText: '汁物1＋おかず3＋ご飯', explanationDetail: '一汁三菜：ご飯＋汁物1品（みそ汁）＋主菜1品（肉・魚・卵）＋副菜2品（野菜・豆腐等）。栄養バランスが自然に整う和食の知恵。2013年ユネスコ無形文化遺産に「和食」が登録されました。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_8', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「たんぱく質」が豊富な食品はどれですか？', choices: ['肉・魚・卵・大豆', 'ご飯・パン・めん', 'バター・油', 'お菓子・ジュース'], correctIndex: 0, feedbackCorrect: 'せいかい！肉・魚・卵・大豆はたんぱく質が豊富だよ！', feedbackIncorrect: 'ざんねん！たんぱく質は肉・魚・卵・大豆製品（豆腐・納豆等）に多く含まれるよ！', hintText: '体の材料になる栄養素', explanationDetail: 'タンパク質は体の筋肉・臓器・皮膚・髪の毛の材料。動物性（肉・魚・卵・乳製品）と植物性（大豆・豆腐・納豆）に分かれます。アミノ酸9種類は体内で作れない「必須アミノ酸」として食事から摂る必要があります。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_9', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '調理前に必ず行うことはどれですか？', choices: ['手を石けんでよく洗う', '音楽をかける', 'エプロンだけつける', '冷蔵庫を開ける'], correctIndex: 0, feedbackCorrect: 'せいかい！調理前の手洗いは食中毒防止の基本だよ！', feedbackIncorrect: 'ざんねん！調理前には必ず石けんで手を洗うことが食中毒防止の基本だよ！', hintText: '衛生管理の第一歩', explanationDetail: '調理前の準備：①石けんで手を30秒以上洗う②エプロン・三角巾を付ける③調理台を清潔にする④材料・道具を揃える。手には様々な菌がついているため、洗わないと食品を汚染します。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_10', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「電子レンジ」で使えない容器はどれですか？', choices: ['金属製の容器・アルミホイル', '陶器の皿', '耐熱ガラス', '電子レンジ対応プラスチック容器'], correctIndex: 0, feedbackCorrect: 'せいかい！金属は電子レンジで火花が散って危険だよ！', feedbackIncorrect: 'ざんねん！金属容器やアルミホイルは電子レンジで火花（スパーク）が発生して危険だよ！', hintText: '金属はNG！', explanationDetail: '電子レンジNG：金属製容器・アルミホイル（スパーク発生）・密閉容器（爆発の恐れ）・卵（そのまま加熱すると破裂）。電子レンジはマイクロ波で水分子を振動させて加熱します。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_11', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「食品表示（しょくひんひょうじ）」を見るとわかることはどれですか？', choices: ['原材料・栄養成分・賞味期限・アレルゲンなど', '値段だけ', '調理方法だけ', '農家の名前だけ'], correctIndex: 0, feedbackCorrect: 'せいかい！食品表示は安全に食べるための大切な情報だよ！', feedbackIncorrect: 'ざんねん！食品表示には名称・原材料・内容量・賞味期限・保存方法・製造者・栄養成分などが書かれているよ！', hintText: '食品の安全情報が全部わかる', explanationDetail: '食品表示法（2015年）で義務付けられた表示：原材料名（多い順）・アレルゲン（8品目義務：小麦・卵・乳・えび・かに・落花生・そば・くるみ）・栄養成分（エネルギー・タンパク質・脂質・炭水化物・塩分）・賞味/消費期限。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_12', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「フードロス（食品ロス）」とはどういう問題ですか？', choices: ['まだ食べられるのに捨てられる食品の問題', '食品が売り切れる問題', '食品が高すぎる問題', '食品の味が悪い問題'], correctIndex: 0, feedbackCorrect: 'せいかい！フードロスは世界の食糧問題とも直結する深刻な問題だよ！', feedbackIncorrect: 'ざんねん！フードロス（食品ロス）はまだ食べられるのに捨てられる食品の問題だよ！', hintText: '食べられるのに捨てられる', explanationDetail: '日本では年間約522万トンの食品ロスが発生（2021年）。原因：①過剰発注・過剰生産②賞味期限切れ③食べ残し。解決策：①必要な量だけ買う②在庫管理③冷凍保存の活用④残り物の再利用。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_13', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「食の安全」を守るために消費者ができることはどれですか？', choices: ['賞味期限の確認・産地確認・調理時の衛生管理など', '値段が高いものだけ買う', '有名ブランドだけ信頼する', '外食だけにする'], correctIndex: 0, feedbackCorrect: 'せいかい！消費者自身が食の安全を確認することが大切だよ！', feedbackIncorrect: 'ざんねん！食の安全のために消費者ができることは賞味期限・産地の確認、適切な保存・調理などたくさんあるよ！', hintText: '消費者自身が安全を確認する', explanationDetail: '食の安全を守る：①食品表示の確認②賞味期限・消費期限の確認③適切な保存温度の管理④十分な加熱調理⑤産地・原材料の確認⑥信頼できる情報源の活用。食品安全委員会が国の安全基準を管理しています。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_14', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「地産地消（ちさんちしょう）」とはどういうことですか？', choices: ['地元で作られた食材を地元で消費すること', '外国から輸入した食材を食べること', '工場で作られた食品だけを食べること', 'オーガニック食品だけを食べること'], correctIndex: 0, feedbackCorrect: 'せいかい！地産地消は環境・経済・健康の全てに良い食の取り組みだよ！', feedbackIncorrect: 'ざんねん！地産地消は地元で生産された農作物・食品を地元で消費する取り組みだよ！', hintText: '地元で作って地元で食べる', explanationDetail: '地産地消のメリット：①輸送コスト・CO2削減（環境）②地元農家の収入を支える（経済）③新鮮な食材が食べられる（健康）④フードマイレージの削減。学校給食での地産地消も推進されています。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_32_15', stage: LiteracyStage.stage32, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「食文化（しょくぶんか）」を大切にすることはなぜ重要ですか？', choices: ['伝統・地域のアイデンティティを守り次世代に伝えるため', '新しい料理は全て悪いから', '外国の食べ物は体に悪いから', '食文化は変わらないから'], correctIndex: 0, feedbackCorrect: 'せいかい！食文化は地域や民族のアイデンティティそのものだよ！', feedbackIncorrect: 'ざんねん！食文化はその地域の気候・歴史・価値観が凝縮されたもので、次世代への伝承が大切だよ！', hintText: '伝統・アイデンティティを守る', explanationDetail: '食文化の多様性：和食（日本）・フランス料理・メキシコ料理・地中海料理など多くの食文化がユネスコ無形文化遺産に登録。それぞれの地域の気候・歴史・宗教が反映されています。食文化の継承は多様性の保護でもあります。', theme: 'home_ec'),
];

const stage33Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_33_1', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '針に糸を通した後、糸が抜けないようにするためにするのはどれですか？', choices: ['糸の端に玉結びをする', '糸をテープで留める', '糸を短くする', '糸を2本使う'], correctIndex: 0, feedbackCorrect: 'せいかい！玉結びをすることで糸が布から抜けないようになるよ！', feedbackIncorrect: 'ざんねん！縫い始める前に糸の端に「玉結び」を作ると糸が抜けないよ！', hintText: '糸の端にコブを作る', explanationDetail: '玉結びの作り方：①針に糸を通す②糸を人差し指に1周巻く③巻いた部分を親指でしっかり押さえながら糸を引く④小さなコブができる。縫い始めに必ず行います。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_2', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '洗濯物を干すとき、一番乾きやすいのはどれですか？', choices: ['日当たりがよく風通しの良い場所に間隔をあけて干す', '重ねてまとめて干す', '日陰に干す', '全部まとめて1箇所に干す'], correctIndex: 0, feedbackCorrect: 'せいかい！風通しよく間隔をあけると早く乾くよ！', feedbackIncorrect: 'ざんねん！洗濯物は日当たり・風通しの良い場所で、重ならないよう間隔を空けて干すのが基本だよ！', hintText: '日当たり・風通し・間隔', explanationDetail: '洗濯物の干し方：①衿・袖など厚い部分を外側にする②ハンガーはゆとりを持って掛ける③裏返しにすると日焼けを防げる④風通しをよくするためスペースを空ける。乾燥剤・扇風機を使うと早く乾きます。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_3', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '衣類の「洗濯表示」に手の絵がある場合はどういう意味ですか？', choices: ['手洗いができる', '洗濯できない', '乾燥機が使える', 'アイロンをかける'], correctIndex: 0, feedbackCorrect: 'せいかい！手の絵は手洗いOKの表示だよ！', feedbackIncorrect: 'ざんねん！洗濯表示の手の絵は「手洗いができる」という意味だよ！', hintText: '手の形が描かれている', explanationDetail: '洗濯表示（JIS L 0001）：桶マーク（洗濯方法）・三角（漂白）・四角（乾燥）・アイロン・ドライクリーニングの5種類。2016年から国際規格（ISO）に統一されました。衣類を長持ちさせるために確認する習慣をつけましょう。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_4', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「なみ縫い」とはどういう縫い方ですか？', choices: ['布に針を等間隔に交互に刺して進む基本の縫い方', '糸を交差させて縫う方法', '布の端だけを縫う方法', '二本の糸を使う縫い方'], correctIndex: 0, feedbackCorrect: 'せいかい！なみ縫いは基本の縫い方で、等間隔に刺していくよ！', feedbackIncorrect: 'ざんねん！なみ縫いは布の表・裏に交互に等間隔で針を刺して進む、最も基本的な手縫いの方法だよ！', hintText: '布に等間隔で針を刺して進む', explanationDetail: '基本の縫い方：①なみ縫い（等間隔に進む）②返し縫い（1針ずつ戻る・丈夫）③まつり縫い（布の端を折り込んで縫う）。なみ縫いは袋物・しつけ縫いによく使います。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_5', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '身の回りを整理整頓する目的は何ですか？', choices: ['探し物を減らし、生活をしやすくするため', '部屋を広く見せるため', '友達に見せるため', '先生に褒められるため'], correctIndex: 0, feedbackCorrect: 'せいかい！整理整頓で生活が快適になり時間も節約できるよ！', feedbackIncorrect: 'ざんねん！整理整頓の目的は探し物の時間を減らし、安全で快適な生活をつくるためだよ！', hintText: '生活を楽にするため', explanationDetail: '整理整頓の効果：①探し物の時間削減②安全（つまずき防止）③掃除がしやすい④物を大切にする習慣。「整理」＝いらない物を捨てる「整頓」＝必要な物を決まった場所に置く、の2つが大切。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_6', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「アイロンがけ」で気をつけることはどれですか？', choices: ['温度設定を確認し、スチームを正しく使い、熱いうちは触らない', '最高温度で全ての衣類をかける', '濡れたまま使わない', 'どんな衣類も同じ温度でかける'], correctIndex: 0, feedbackCorrect: 'せいかい！アイロンは温度管理と火傷防止が大切だよ！', feedbackIncorrect: 'ざんねん！アイロンは衣類の素材に合った温度設定・スチームを正しく使い、熱いアイロンに触れないよう注意するよ！', hintText: '温度設定と火傷防止', explanationDetail: 'アイロン温度：高（綿・麻）・中（ウール・ポリエステル混）・低（ナイロン・アクリル等）。低温で設定しても熱いので火傷に注意。使用後は必ず電源を切り、熱が冷めるまで立てて置きます。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_7', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「エコな生活」を家庭でできる取り組みはどれですか？', choices: ['節電・節水・ゴミの分別・リサイクル', '電気を使わない生活をする', '水を全く使わない', '買い物をやめる'], correctIndex: 0, feedbackCorrect: 'せいかい！小さな積み重ねが環境を守るよ！', feedbackIncorrect: 'ざんねん！家庭でできるエコな取り組みには節電・節水・ゴミ分別・リユース・リサイクルなどがあるよ！', hintText: '節電・節水・ゴミ分別', explanationDetail: '家庭でできるSDGs：①LED電球・省エネ家電（節電）②シャワー時間短縮・節水型器具（節水）③ゴミの正しい分別④マイバッグ・マイボトルの使用⑤衣類のリペア・リユース。一人ひとりの行動が積み重なって変化を生みます。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_8', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「消費生活（しょうひせいかつ）」で大切なことはどれですか？', choices: ['必要かどうかを考えてから買い、無駄遣いを減らすこと', '気に入ったものは全部買う', '値段が高いものほど良い', '広告に書いてあることは全て正しい'], correctIndex: 0, feedbackCorrect: 'せいかい！「本当に必要か」を考えることが賢い消費者の第一歩だよ！', feedbackIncorrect: 'ざんねん！賢い消費生活の基本は「必要かどうか」「品質・価格は適切か」を考えて判断することだよ！', hintText: '必要かどうかを考えてから買う', explanationDetail: '消費者の権利と責任：①安全を求める権利②情報を知る権利③選ぶ権利④意見を反映させる権利。消費者基本法で保護されています。広告・キャッチコピーに惑わされず、必要性・品質・価格を比較する習慣が大切。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_9', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: 'ボタン付けで「返し縫い」をする目的はどれですか？', choices: ['糸が緩まないよう固定するため', '見た目をきれいにするため', '針を保護するため', '速く縫うため'], correctIndex: 0, feedbackCorrect: 'せいかい！返し縫いでボタンがしっかり固定されるよ！', feedbackIncorrect: 'ざんねん！返し縫いは糸を交差させて固定し、ボタンが外れにくくするために行うよ！', hintText: '糸をしっかり固定する', explanationDetail: 'ボタン付けの手順：①位置を決める②玉結びした糸で表から通す③ボタンの穴を数回通す④ボタンの根元に糸を巻く⑤玉止めをする。返し縫いをすることで糸がほどけにくくなります。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_10', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「掃除」の効果として正しいのはどれですか？', choices: ['清潔・安全・快適な生活環境を作り、健康を守る', '掃除は意味がない', '見た目だけの問題', '運動のためだけ'], correctIndex: 0, feedbackCorrect: 'せいかい！掃除は健康・安全・快適さを守る大切な生活習慣だよ！', feedbackIncorrect: 'ざんねん！掃除はアレルゲン（ほこり・ダニ）の除去・転倒防止・精神的快適さなど健康に直接関わるよ！', hintText: '健康・安全・快適さを守る', explanationDetail: '掃除の効果：①ほこり・ダニ・カビを除去（アレルギー予防）②床の整理で転倒防止③カビ・菌の繁殖抑制④生活の見通しが良くなり精神的快適さ向上。「5S活動」（整理・整頓・清掃・清潔・躾）は職場でも基本です。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_11', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「サステナブルファッション」とはどういうことですか？', choices: ['環境・社会に配慮した持続可能な衣類の生産・消費のあり方', '最新のファッションを常に買うこと', '安い服だけを買うこと', '派手な服だけを着ること'], correctIndex: 0, feedbackCorrect: 'せいかい！ファッションも環境・社会への影響を考えることが大切だよ！', feedbackIncorrect: 'ざんねん！サステナブルファッションは衣類の環境負荷（水・化学物質・CO2）や労働者の権利を考えた取り組みだよ！', hintText: '環境・社会に配慮した衣類の選択', explanationDetail: 'ファストファッションの問題：大量生産・大量廃棄・発展途上国での劣悪労働。解決策：長く着られる服を選ぶ・修繕して使う・古着・リユース・フェアトレード製品。「誰が作ったか」を考えて買うことが重要。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_12', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「生活時間（せいかつじかん）」の管理で大切なことはどれですか？', choices: ['睡眠・食事・学習・遊び・家事などのバランスをとること', '勉強だけをすること', '睡眠をできるだけ減らすこと', 'ゲームを中心に生活を組む'], correctIndex: 0, feedbackCorrect: 'せいかい！生活時間のバランスが健康・学力・幸福感に影響するよ！', feedbackIncorrect: 'ざんねん！生活時間の管理は睡眠・食事・学習・休養・家族の時間などのバランスを意識することが大切だよ！', hintText: '睡眠・食事・学習のバランス', explanationDetail: '生活時間の管理：①小学生の推奨睡眠時間9〜12時間②規則正しい食事時間③学習と遊びのバランス④スクリーンタイム管理。生活リズムが乱れると学習効率・免疫力・精神健康に悪影響が出ます。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_13', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「家事分担（かじぶんたん）」が家庭で重要な理由はどれですか？', choices: ['全員が協力することで家族の絆が深まり、一人への負担が減るから', '子どもには家事は不要だから', '家事は女性だけがするから', '家事はお金で全て解決できるから'], correctIndex: 0, feedbackCorrect: 'せいかい！家族みんなで家事を分担することが現代の家族の基本だよ！', feedbackIncorrect: 'ざんねん！家事分担は特定の人への負担を減らし、家族全員が協力して生活を支え合うために重要だよ！', hintText: '家族みんなで協力する', explanationDetail: '家事の定義：料理・洗濯・掃除・育児・介護など家庭を維持する無償労働。日本では女性の家事負担が高い傾向（内閣府調査）。子どもも家事を手伝うことで生活スキル・協調性・自立心が育ちます。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_14', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「住まいの安全」で地震に備えるために大切なことはどれですか？', choices: ['家具の固定・避難経路の確認・非常用持ち出し袋の準備', '背の高い家具の上に重い物を置く', '避難経路を考えない', '非常用品は不要'], correctIndex: 0, feedbackCorrect: 'せいかい！日頃からの備えが命を守るよ！', feedbackIncorrect: 'ざんねん！地震に備えた住まいの安全対策は家具の固定・避難経路確認・非常持ち出し袋が基本だよ！', hintText: '家具固定・避難経路・非常袋', explanationDetail: '地震対策の3つの基本：①家具転倒防止（L型金具・突っ張り棒で固定）②避難経路確認（出口の確認・避難場所の把握）③非常用持ち出し袋（水・食料・薬・懐中電灯・携帯ラジオなど3日分）。', theme: 'home_ec'),
  TaikuQuestion(id: 'tai_33_15', stage: LiteracyStage.stage33, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「ユニバーサルデザイン」を住まいに取り入れる目的はどれですか？', choices: ['年齢・障がいに関わらず誰もが使いやすい住まいをつくるため', '豪華な住まいをつくるため', '若者だけが使いやすい住まいをつくるため', 'コストを下げるため'], correctIndex: 0, feedbackCorrect: 'せいかい！ユニバーサルデザインはすべての人が使いやすい設計思想だよ！', feedbackIncorrect: 'ざんねん！住まいのユニバーサルデザインは高齢者・障がいのある方・子ども・外国人など全ての人が使いやすい設計を目指すよ！', hintText: '誰もが使いやすい設計', explanationDetail: 'ユニバーサルデザイン（UD）の7原則：①公平な使用②柔軟性③シンプル④情報知覚⑤エラー許容⑥省力化⑦スペース確保。住まいの例：段差なし・手すり・広い廊下・スロープ。バリアフリーと重なる部分も多いです。', theme: 'home_ec'),
];

const stage34Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_34_1', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「プログラム」とはどういうものですか？', choices: ['コンピュータに何をするか順番に指示したもの', 'テレビ番組の予定表', '学校の時間割', 'お菓子のレシピ'], correctIndex: 0, feedbackCorrect: 'せいかい！プログラムはコンピュータへの命令書だよ！', feedbackIncorrect: 'ざんねん！プログラムはコンピュータに「これをしてください」と順番に命令を書いたものだよ！', hintText: 'コンピュータへの命令の順番', explanationDetail: 'プログラム（Program）はコンピュータに実行させる命令の集まり。コンピュータは人間の言葉を理解できないので、プログラミング言語という特別な言語で書きます。ゲーム・アプリ・ウェブサイト全てプログラムで動いています。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_2', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'プログラミングの「順次（じゅんじ）」とはどういう考え方ですか？', choices: ['命令を上から順番に一つずつ実行すること', '命令をランダムに実行すること', '同時に全部実行すること', '一番難しい命令から実行すること'], correctIndex: 0, feedbackCorrect: 'せいかい！プログラムは基本的に上から順番に実行されるよ！', feedbackIncorrect: 'ざんねん！順次は命令を書いた順番に上から一つずつ実行するプログラムの基本だよ！', hintText: '上から順番に実行', explanationDetail: 'プログラムの3つの基本構造：①順次（上から順番に実行）②分岐（条件によって処理を分ける）③反復（繰り返し）。この3つの組み合わせで全てのプログラムが作れます。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_3', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「Scratch（スクラッチ）」とはどういうプログラミングツールですか？', choices: ['ブロックをつなげてゲームやアニメが作れる子ども向けプログラミング環境', '音楽を作るアプリ', '絵を描くアプリ', '動画を見るアプリ'], correctIndex: 0, feedbackCorrect: 'せいかい！Scratchはブロックを組み合わせてプログラミングが楽しく学べるツールだよ！', feedbackIncorrect: 'ざんねん！ScratchはMITが開発したビジュアルプログラミング環境で、ブロックをつなげてゲームやアニメが作れるよ！', hintText: 'ブロックを組み合わせてプログラム', explanationDetail: 'Scratchは2007年にMIT（マサチューセッツ工科大学）が開発した無料のプログラミング学習ツール。ブロックを組み合わせるビジュアルプログラミングなので、コードを書かなくても動くプログラムが作れます。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_4', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「アルゴリズム」とはどういうものですか？', choices: ['問題を解くための手順・やり方のこと', 'コンピュータのブランド名', '電気の流れ方', 'インターネットの速さ'], correctIndex: 0, feedbackCorrect: 'せいかい！アルゴリズムは問題を解くための手順だよ！', feedbackIncorrect: 'ざんねん！アルゴリズムは問題を解くための手順・方法のことで、料理のレシピや地図のルートも一種のアルゴリズムだよ！', hintText: '問題を解く手順', explanationDetail: 'アルゴリズムの例：①地図アプリが最短ルートを探す手順②検索エンジンが関連する情報を探す手順③料理のレシピ。良いアルゴリズムは①正確②効率的③シンプルである必要があります。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_5', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'プログラムの「繰り返し（ループ）」とはどういうことですか？', choices: ['同じ命令を何度も繰り返すこと', '命令を一回だけ実行すること', 'プログラムを止めること', 'ランダムに動かすこと'], correctIndex: 0, feedbackCorrect: 'せいかい！ループを使うと同じ処理を効率よく繰り返せるよ！', feedbackIncorrect: 'ざんねん！繰り返し（ループ）は同じ命令を何度も自動的に実行することで、プログラムを短くできるよ！', hintText: '同じ命令を何度も実行', explanationDetail: 'ループの例：「10回おじぎをする」をプログラムする場合、命令を10回書く代わりに「10回繰り返す」ブロックを使うと短く書けます。for文・while文などがプログラミング言語のループ構文です。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_6', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: 'プログラミングの「条件分岐（もし〜なら）」とはどういうものですか？', choices: ['ある条件が当てはまるかどうかで実行する処理を変えること', '命令を順番に実行すること', '命令を繰り返すこと', '処理を止めること'], correctIndex: 0, feedbackCorrect: 'せいかい！条件分岐でプログラムが状況に合わせて動けるようになるよ！', feedbackIncorrect: 'ざんねん！条件分岐（if文）は「もし○○なら△△する、そうでなければ□□する」という条件によって処理を変えるしくみだよ！', hintText: 'もし〜なら・そうでなければ', explanationDetail: '条件分岐の例：「もし雨なら傘を持つ、晴れなら帽子をかぶる」。ゲームでは「もし敵に当たったらゲームオーバー」などに使います。プログラムに「判断」の力を与えます。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_7', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「デバッグ（debug）」とはどういうことですか？', choices: ['プログラムのエラー（バグ）を見つけて修正すること', 'プログラムを保存すること', '新しいプログラムを作ること', 'プログラムを消すこと'], correctIndex: 0, feedbackCorrect: 'せいかい！バグを見つけて直すことをデバッグというよ！', feedbackIncorrect: 'ざんねん！デバッグはプログラムの間違い（バグ）を見つけて修正する作業だよ！', hintText: 'バグ＝エラー、デバッグ＝修正', explanationDetail: 'バグ（Bug）はプログラムの間違いや不具合。語源はコンピュータに虫（Bug）が入り込んで故障したという故事（1947年）。デバッグは①バグを発見②原因を特定③修正④テストという手順で行います。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_8', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「センサー」とはどういう機器ですか？', choices: ['温度・光・音・動きなどを検知して信号に変える装置', '計算をする装置', '画像を表示する装置', '音を出す装置'], correctIndex: 0, feedbackCorrect: 'せいかい！センサーは周りの状態を感知してコンピュータに伝えるよ！', feedbackIncorrect: 'ざんねん！センサーは温度・光・音・動き・圧力などの物理的な変化を感知して電気信号に変える装置だよ！', hintText: '周りの状態を感知する装置', explanationDetail: 'センサーの例：①温度センサー（エアコン・体温計）②光センサー（自動ドア・スマホの明るさ調整）③加速度センサー（スマホの傾き検知）④GPS（位置情報）。IoT機器はセンサーとインターネットで機能します。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_9', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「AI（人工知能）」はどのように判断・学習しますか？', choices: ['大量のデータからパターンを学習して判断する', '人間が一つずつ教えた通りにしか動かない', 'ランダムに答えを出す', '計算式だけで全て解く'], correctIndex: 0, feedbackCorrect: 'せいかい！AIは大量のデータから学ぶ機械学習でどんどん賢くなるよ！', feedbackIncorrect: 'ざんねん！現代のAIは大量のデータを学習し、そのパターンを使って新しい状況を判断する「機械学習」を使っているよ！', hintText: 'データからパターンを学ぶ', explanationDetail: 'AIの種類：①機械学習（データからパターンを学習）②深層学習（ニューラルネットワークで複雑なパターン学習）③生成AI（ChatGPT・画像生成）。AIは画像認識・音声認識・翻訳・医療診断など幅広く活用されています。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_10', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「プログラミング的思考」で大切な考え方はどれですか？', choices: ['問題を小さく分解して順番に考え、効率よく解決する方法を見つけること', '素早く答えを出すこと', 'コンピュータを使わないこと', '感覚で解決すること'], correctIndex: 0, feedbackCorrect: 'せいかい！プログラミング的思考は問題解決の力全般を高めるよ！', feedbackIncorrect: 'ざんねん！プログラミング的思考は問題を分解し・パターンを見つけ・手順を組み立てて解決する論理的思考力だよ！', hintText: '問題を分解して手順を考える', explanationDetail: 'プログラミング的思考の要素：①分解（大きな問題を小さな問題に分ける）②パターン認識（共通点を見つける）③抽象化（本質を捉える）④アルゴリズム（手順を考える）。コンピュータ以外の問題解決にも役立ちます。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_11', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「ビッグデータ」とはどういうものですか？', choices: ['従来の方法では処理しきれない膨大な量・種類のデータ', 'データを大きなファイルにまとめたもの', '高価なコンピュータのデータ', '秘密のデータ'], correctIndex: 0, feedbackCorrect: 'せいかい！ビッグデータは現代社会のあらゆる意思決定に使われているよ！', feedbackIncorrect: 'ざんねん！ビッグデータは量・速度・多様性が従来の範囲を超えた膨大なデータ群で、AIの学習にも使われるよ！', hintText: '膨大な量・種類のデータ', explanationDetail: 'ビッグデータの3V：①Volume（量が膨大）②Velocity（速度が速い）③Variety（種類が多様）。活用例：SNSの行動データで広告配信・医療データで新薬開発・交通データで渋滞予測。プライバシー保護が課題。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_12', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「IoT（Internet of Things）」とはどういうことですか？', choices: ['様々な機器がインターネットにつながって情報をやりとりすること', 'インターネットのない環境でのコンピュータ使用', 'テレビ番組をネットで見ること', 'スマートフォンのアプリ'], correctIndex: 0, feedbackCorrect: 'せいかい！IoTは身の回りの物がインターネットでつながる世界だよ！', feedbackIncorrect: 'ざんねん！IoTは家電・車・工場の機械などがインターネットでつながり、データを収集・活用するしくみだよ！', hintText: 'あらゆる機器がネットにつながる', explanationDetail: 'IoT（モノのインターネット）の例：スマートホーム（エアコン・照明をスマホで操作）・スマートウォッチ（健康データ収集）・自動運転（センサーとネット接続）・工場の予防保全。2030年には世界で500億個以上のIoT機器が使用される予測。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_13', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「オープンソース」とはどういうことですか？', choices: ['プログラムのソースコードを無料で公開し、誰でも改良・再配布できること', 'コンピュータの電源を入れること', '高価なソフトウェアのこと', 'クラウドサービス'], correctIndex: 0, feedbackCorrect: 'せいかい！オープンソースはIT業界の革命的な共有・協力の文化だよ！', feedbackIncorrect: 'ざんねん！オープンソースはプログラムのソースコードを公開し、世界中の開発者が改良・再利用できる開発スタイルだよ！', hintText: 'ソースコードを無料公開', explanationDetail: 'オープンソースの例：Linux（OS）・Firefox（ブラウザ）・WordPress（CMS）・Python（プログラミング言語）。世界中の開発者が貢献して改良されます。インターネットのインフラの多くはオープンソースで成り立っています。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_14', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「クラウドコンピューティング」とはどういうことですか？', choices: ['インターネット経由でサーバーの計算力・保存容量を使うサービス', '雲の中にコンピュータがある', '無線LANのこと', 'スマートフォンのバックアップ'], correctIndex: 0, feedbackCorrect: 'せいかい！クラウドは現代のICTインフラの中心だよ！', feedbackIncorrect: 'ざんねん！クラウドコンピューティングはインターネット経由で遠くのサーバーの計算力・保存容量・サービスを利用するしくみだよ！', hintText: 'インターネット経由でサービスを使う', explanationDetail: 'クラウドの例：Google Drive・iCloud（ファイル保存）・YouTube（動画）・Amazon Web Services（企業向け）。自分のコンピュータに保存しなくてもネット接続があればどこからでもアクセスできます。', theme: 'ict'),
  TaikuQuestion(id: 'tai_34_15', stage: LiteracyStage.stage34, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: 'プログラムの「変数（へんすう）」とはどういうものですか？', choices: ['データを一時的に保存しておく名前のついた入れ物', '計算の記号', 'コンピュータの部品', 'キーボードのキー'], correctIndex: 0, feedbackCorrect: 'せいかい！変数はプログラムでデータを管理するための基本概念だよ！', feedbackIncorrect: 'ざんねん！変数はプログラム上でデータ（数値・文字など）を保存しておく名前のついた入れ物だよ！', hintText: 'データを入れる名前つきの箱', explanationDetail: '変数の例：score（点数）という変数に10を入れ、敵を倒すたびに+1する。プログラムは変数を使ってデータを保持・変更します。変数名・型・スコープが重要な概念です。', theme: 'ict'),
];

const stage35Questions = <TaikuQuestion>[
  TaikuQuestion(id: 'tai_35_1', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'パスワードを決めるとき、一番安全なのはどれですか？', choices: ['英数字や記号を混ぜた長いパスワード', '自分の名前', '「1234」など簡単な数字', '誰にでも教えてもいいパスワード'], correctIndex: 0, feedbackCorrect: 'せいかい！長くて複雑なパスワードが一番安全だよ！', feedbackIncorrect: 'ざんねん！パスワードは英字・数字・記号を混ぜた長いものにして、誰にも教えないことが大切だよ！', hintText: '長くて複雑なパスワード', explanationDetail: '安全なパスワードの条件：①8文字以上②英大文字・小文字・数字・記号を混ぜる③名前・生年月日などの個人情報を使わない④サービスごとに異なるパスワードを使う。パスワードマネージャーを活用するのも良い方法です。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_2', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'インターネットで知らない人に教えてはいけないことはどれですか？', choices: ['住所・電話番号・学校名など個人情報', '好きな食べ物', '好きなゲーム', '好きな色'], correctIndex: 0, feedbackCorrect: 'せいかい！住所・電話番号・学校名は絶対ネットで教えてはいけないよ！', feedbackIncorrect: 'ざんねん！住所・電話番号・学校名・家族の情報などの個人情報は絶対にインターネット上で公開・教えてはいけないよ！', hintText: '個人が特定される情報', explanationDetail: '個人情報とは特定の個人を識別できる情報。①氏名②住所③電話番号④メールアドレス⑤学校名⑥顔写真。インターネットに一度公開した情報は完全には削除できません（デジタルタトゥー）。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_3', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'インターネットの情報が「正しい」かどうかを確かめるためにはどうしますか？', choices: ['複数の信頼できるサイトで確認する', '最初に見た情報を信じる', '友達が言ったら信じる', '古い情報でも信じる'], correctIndex: 0, feedbackCorrect: 'せいかい！一つだけの情報を信じず、複数のソースで確認することが大切だよ！', feedbackIncorrect: 'ざんねん！インターネットの情報は誰でも書けるので、複数の信頼できる情報源（ソース）で確認することが大切だよ！', hintText: '複数のソースで確認する', explanationDetail: 'メディアリテラシー：①誰が情報を発信しているか確認②複数の情報源で裏付けを取る③情報の日付を確認（古くないか）④専門家・公的機関の情報を優先。フェイクニュースを見分ける力が現代では必須です。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_4', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: '「ネットいじめ（サイバーいじめ）」が問題な理由はどれですか？', choices: ['24時間・世界中でいじめが広がり、完全に消えない記録が残るから', '画面で見るから目が疲れるから', '電気代がかかるから', 'スマホが使えなくなるから'], correctIndex: 0, feedbackCorrect: 'せいかい！ネットいじめは現実のいじめより深刻になりやすいよ！', feedbackIncorrect: 'ざんねん！ネットいじめは匿名で拡散しやすく、24時間追いかけてきて、記録が消えない点で現実のいじめより深刻になりやすいよ！', hintText: '24時間・拡散・記録が残る', explanationDetail: 'ネットいじめの特徴：①匿名性で加害者が増えやすい②24時間・場所を問わず②拡散で被害が広がる④デジタルデータは完全削除が難しい。被害を受けたら一人で抱え込まず大人（親・先生）に相談を。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_5', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.low, contentType: ContentLiteracyType.fundamental, difficultyRank: 1, questionText: 'スマホやゲームを長時間使いすぎた場合の体への影響はどれですか？', choices: ['目の疲れ・肩こり・睡眠不足などの健康問題', '体が丈夫になる', '記憶力が上がる', '全く影響なし'], correctIndex: 0, feedbackCorrect: 'せいかい！スクリーンタイムの管理は健康のために大切だよ！', feedbackIncorrect: 'ざんねん！スマホ・ゲームの長時間使用は目の疲れ・肩こり・睡眠不足・集中力の低下などを引き起こすよ！', hintText: '目・肩・睡眠への影響', explanationDetail: 'デジタルデバイスの長時間使用の影響：①ドライアイ・視力低下②肩こり・頭痛③ブルーライトによる睡眠障がい④SNS依存・ゲーム依存⑤運動不足。1時間に1回の休憩・就寝前1時間は画面を見ない習慣が推奨されます。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_6', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「フィッシング詐欺（さぎ）」とはどういうものですか？', choices: ['本物そっくりの偽サイトで個人情報やお金をだまし取ること', '魚釣りのゲーム', 'パソコンの壊れ方', '写真の加工方法'], correctIndex: 0, feedbackCorrect: 'せいかい！フィッシング詐欺は巧妙な罠だから気をつけよう！', feedbackIncorrect: 'ざんねん！フィッシング詐欺は銀行・通販サイトなどの本物そっくりの偽サイトに誘導してIDや個人情報をだまし取る詐欺だよ！', hintText: '本物そっくりの偽サイトで騙す', explanationDetail: 'フィッシング詐欺の手口：①本物そっくりのメール・SMS送信②偽サイトに誘導③IDパスワード・クレジットカード番号を入力させる。確認方法：URLを確認する（https://が本物の企業ドメインか）・公式アプリを使う。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_7', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「著作権」に反しないインターネットの使い方はどれですか？', choices: ['許可を得るか引用のルールに従って使用し、出典を明記する', '気に入った画像は全てダウンロードして自由に使う', 'SNSに何でもアップしてよい', '有名な曲はBGMとして自由に使える'], correctIndex: 0, feedbackCorrect: 'せいかい！ネット上のコンテンツも著作権が守られているよ！', feedbackIncorrect: 'ざんねん！ネット上の画像・音楽・文章も著作権があり、無断使用は違法だよ！引用ルールに従い出典を明記しよう！', hintText: '出典を明記・許可を得る', explanationDetail: '著作権の基本：作成した瞬間に著作権が発生。ネット上の画像・音楽・文章を無断で使うと著作権法違反。引用は①必要最小限②出典を明記③引用の量が少ないなどのルールがあります。「クリエイティブコモンズ」ライセンスで自由に使えるコンテンツもあります。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_8', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「SNS」を使うときに気をつけることはどれですか？', choices: ['個人情報を載せない・誹謗中傷をしない・情報の真偽を確認する', '感じたことは何でもすぐ投稿する', '友達の写真を許可なく載せる', '見知らぬ人の連絡先を気軽に交換する'], correctIndex: 0, feedbackCorrect: 'せいかい！SNSの正しい使い方は自分も他人も守るよ！', feedbackIncorrect: 'ざんねん！SNSでは個人情報保護・誹謗中傷をしない・フェイク情報を広めないなどのルールを守ることが大切だよ！', hintText: '個人情報・誹謗中傷・フェイク情報', explanationDetail: 'SNS利用の注意点：①個人情報（写真を含む）を公開しない②人を傷つける投稿をしない③情報の真偽を確かめてから拡散④知らない人と個人的に会わない⑤一度投稿した情報は消えない。「投稿する前に3秒考える」習慣が大切。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_9', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「情報モラル」とはどういうことですか？', choices: ['ICTを正しく・安全に使うための道徳的な考え方や行動', 'コンピュータの使い方技術', 'プログラミングのルール', 'インターネットの速さ'], correctIndex: 0, feedbackCorrect: 'せいかい！情報モラルはデジタル社会で生きるための大切な教育だよ！', feedbackIncorrect: 'ざんねん！情報モラルはICTを安全・適切・倫理的に使うための知識・態度・判断力のことだよ！', hintText: 'ICTの正しい使い方の倫理', explanationDetail: '情報モラルの内容：①情報セキュリティ②著作権・プライバシー③ネットいじめ防止④情報の真偽判断（メディアリテラシー）⑤健康的なICT使用。文部科学省の学習指導要領でも重要視されています。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_10', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.mid, contentType: ContentLiteracyType.practical, difficultyRank: 2, questionText: '「デジタルデバイド（Digital Divide）」とはどういう問題ですか？', choices: ['ICTを使える人と使えない人の間の格差', 'コンピュータが壊れること', 'インターネットが遅くなること', 'アプリが古くなること'], correctIndex: 0, feedbackCorrect: 'せいかい！デジタルデバイドは社会の公平性に関わる重要な問題だよ！', feedbackIncorrect: 'ざんねん！デジタルデバイドはICTにアクセスできる人とできない人の間に生まれる格差・不平等の問題だよ！', hintText: 'ICTが使える人・使えない人の格差', explanationDetail: 'デジタルデバイドの原因：①経済格差（機器・通信費が払えない）②地域格差（農村・途上国に回線なし）③年齢・スキル格差（高齢者・障がい者）。GIGAスクール構想は学校での格差解消を目指しています。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_11', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「個人情報保護法（こじんじょうほうほごほう）」の目的はどれですか？', choices: ['個人情報を適切に取り扱い、個人の権利・利益を守ること', '企業が個人情報を自由に使えるようにすること', '個人情報を全て公開すること', 'SNSを禁止すること'], correctIndex: 0, feedbackCorrect: 'せいかい！個人情報保護法は個人のプライバシーを守る大切な法律だよ！', feedbackIncorrect: 'ざんねん！個人情報保護法は個人情報の不正取得・利用・流出を防いで個人の権利・利益を守るための法律だよ！', hintText: '個人の権利・利益を守る', explanationDetail: '個人情報保護法（2003年制定、2022年改正）：企業・団体が個人情報を取得する際は目的を明示・同意を得ることが必要。情報漏えいの罰則あり。EUのGDPR（一般データ保護規則）も国際的な基準として重要。', theme: 'ict'),
  TaikuQuestion(id: 'tai_35_12', stage: LiteracyStage.stage35, gradeLevel: GradeLevel.high, contentType: ContentLiteracyType.critical, difficultyRank: 3, questionText: '「マルウェア（悪意あるソフトウェア）」とはどういうものですか？', choices: ['コンピュータに被害を与えるウイルス・スパイウェア等の悪質なソフト', '古いソフトウェア', '無料のアプリ', '学習用ソフト'], correctIndex: 0, feedbackCorrect: 'せいかい！マルウェアからコンピュータを守るためにセキュリティ対策が必要だよ！', feedbackIncorrect: 'ざんねん！マルウェアはウイルス・ランサムウェア・スパイウェアなどコンピュータや情報に害を与える悪質なソフトウェアの総称だよ！', hintText: '悪意のあるソフトウェア全般', explanationDetail: 'マルウェアの種類：①ウイルス（ファイルに感染・拡散）②ランサムウェア（データを暗号化し身代金要求）③スパイウェア（個人情報を盗む）④トロイの木馬（正常ソフトに偽装）。対策：ウイルス対策ソフト・OS更新・不審リンクを開かない。', theme: 'ict'),
